import{j as n}from"./vendor-react-DzFdt34V.js";import{f as z,C as g,l as L,b as q,d as v,g as P,U as A}from"./LabKit-DU5lFSIc.js";import{s as C,i as E,j,g as _,c as Z,S as K,E as U,k as w,l as B,P as S,a as V,F as T,m as I,C as O,n as G,o as R,q as F,t as D,b as H,d as M,u as N,V as W,T as Q,R as Y,h as J,B as X,x as aa,y as ea,z as m,r as ra,A as ta,D as oa,G as ia}from"./figures-Cv8Dhx1J.js";import{P as na}from"./PairsMemoryGame-CXtJlBKG.js";/* empty css              *//* empty css            */import"./index-Y-VBpkWT.js";import"./vendor-i18n-D_kkcOKx.js";import"./vendor-CAIZfmPq.js";import"./vendor-katex-CdCLdKXh.js";import"./answers-LnVr5_pp.js";import"./answers-DcqakI-w.js";import"./figures-C0-bsRzo.js";import"./plane-BrEro14b.js";const a=(t,u,c)=>({eu:t,es:u,ar:c.replace(/\{,\}/g,".")}),r=t=>({eu:t,es:t,ar:t.replace(/\{,\}/g,".")}),d=t=>{const[u,c=""]=t.split(",");return z(Number(u+c),10**c.length)},o=t=>z(t),s=a("Erabili $\\pi\\approx 3{,}14$.","Usa $\\pi\\approx 3{,}14$.","استعمل $\\pi\\approx 3{,}14$."),$=a("Hurbildu ehunenetara.","Aproxima a las centésimas.","قرّب إلى الأجزاء من مئة."),l=(t,...u)=>({eu:[t.eu,...u.map(c=>c.eu)].join(" "),es:[t.es,...u.map(c=>c.es)].join(" "),ar:[t.ar,...u.map(c=>c.ar)].join(" ")}),da=[{id:1601,prompt:a("Zenbat ertz ditu prisma pentagonal batek?","¿Cuántas aristas tiene un prisma pentagonal?","كم حرفًا للمنشور الخماسي؟"),options:[r("$15$"),r("$10$"),r("$7$")],correctIndex:0,explanation:a("5 goiko oinarrian, 5 behekoan eta 5 alboetan: $3\\cdot 5=15$. 10 erpinak dira eta 7 aurpegiak.","5 en la base de arriba, 5 en la de abajo y 5 laterales: $3\\cdot 5=15$. 10 son los vértices y 7 las caras.","5 في القاعدة العليا و5 في السفلى و5 جانبية: $3\\cdot 5=15$. و10 هي الرؤوس و7 الأوجه."),topic:"elements"},{id:1602,prompt:a("Poliedro ganbil batek 8 aurpegi eta 6 erpin ditu. Zenbat ertz ditu?","Un poliedro convexo tiene 8 caras y 6 vértices. ¿Cuántas aristas tiene?","متعدد أوجه محدّب له 8 أوجه و6 رؤوس. كم حرفًا له؟"),options:[r("$14$"),r("$12$"),r("$16$")],correctIndex:1,explanation:a("Euler: $8+6=12+2$. Oktaedroa da.","Euler: $8+6=12+2$. Es el octaedro.","أويلر: $8+6=12+2$. إنه ثماني الأوجه."),topic:"euler"},{id:1603,prompt:a("Zein poliedro erregularren aurpegiak dira pentagonoak?","¿Qué poliedro regular tiene caras pentagonales?","أي متعدد أوجه منتظم أوجهه مخمسات؟"),options:[a("Ikosaedroa","Icosaedro","عشريني الأوجه"),a("Oktaedroa","Octaedro","ثماني الأوجه"),a("Dodekaedroa","Dodecaedro","اثنا عشري الأوجه")],correctIndex:2,explanation:a("Dodekaedroak 12 pentagono ditu. Ikosaedroa eta oktaedroa triangeluz eginda daude.","El dodecaedro tiene 12 pentágonos. El icosaedro y el octaedro están hechos de triángulos.","لاثني عشري الأوجه 12 مخمسًا. أما عشريني الأوجه وثماني الأوجه فمن مثلثات."),topic:"regular"},{id:1604,prompt:a("Zein da 5 cm-ko ertzeko kubo baten azalera osoa?","¿Cuál es el área total de un cubo de 5 cm de arista?","ما المساحة الكلية لمكعب طول حرفه 5 سم؟"),options:[r("$150$ cm²"),r("$125$ cm²"),r("$25$ cm²")],correctIndex:0,explanation:a("Sei karratu: $6\\cdot 5^{2}=150$. 125 bolumena da, eta 25 aurpegi bakarra.","Seis cuadrados: $6\\cdot 5^{2}=150$. 125 es el volumen y 25 una sola cara.","ستة مربعات: $6\\cdot 5^{2}=150$. و125 هو الحجم و25 وجه واحد."),topic:"prism-area"},{id:1605,prompt:a("Piramide erregular baten alboko triangeluen altuerari zer deitzen zaio?","¿Cómo se llama la altura de los triángulos laterales de una pirámide regular?","ما اسم ارتفاع المثلثات الجانبية في الهرم المنتظم؟"),options:[a("Piramidearen altuera","Altura de la pirámide","ارتفاع الهرم"),a("Piramidearen apotema","Apotema de la pirámide","عامد الهرم"),a("Oinarriaren apotema","Apotema de la base","عامد القاعدة")],correctIndex:1,explanation:a("Apotema alboko aurpegian dago; altuera erpinetik oinarriaren zentrora doa, barrutik.","La apotema está en la cara lateral; la altura va del vértice al centro de la base, por dentro.","العامد على الوجه الجانبي؛ أما الارتفاع فيمتد من الرأس إلى مركز القاعدة من الداخل."),topic:"pyramid-area"},{id:1606,prompt:a("Kono baten erradioa 5 cm da eta altuera 12 cm. Zenbat da sortzailea?","Un cono tiene 5 cm de radio y 12 cm de altura. ¿Cuánto mide la generatriz?","مخروط نصف قطره 5 سم وارتفاعه 12 سم. كم طول راسمه؟"),options:[r("$17$ cm"),r("$7$ cm"),r("$13$ cm")],correctIndex:2,explanation:a("Sortzailea hipotenusa da: $\\sqrt{12^{2}+5^{2}}=\\sqrt{169}=13$.","La generatriz es la hipotenusa: $\\sqrt{12^{2}+5^{2}}=\\sqrt{169}=13$.","الراسم هو الوتر: $\\sqrt{12^{2}+5^{2}}=\\sqrt{169}=13$."),topic:"cone"},{id:1607,prompt:a("Zenbat litro sartzen dira metro kubiko batean?","¿Cuántos litros caben en un metro cúbico?","كم لترًا في المتر المكعب؟"),options:[r("$1000$"),r("$100$"),r("$10$")],correctIndex:0,explanation:a("$1\\ \\text{m}^{3}=1000\\ \\text{dm}^{3}$ eta $1\\ \\text{dm}^{3}=1\\ \\text{L}$.","$1\\ \\text{m}^{3}=1000\\ \\text{dm}^{3}$ y $1\\ \\text{dm}^{3}=1\\ \\text{L}$.","$1\\ \\text{m}^{3}=1000\\ \\text{dm}^{3}$ و$1\\ \\text{dm}^{3}=1\\ \\text{L}$."),topic:"capacity"},{id:1608,prompt:a("Prisma batek 90 cm³ ditu. Zenbat ditu oinarri eta altuera bereko piramideak?","Un prisma tiene 90 cm³. ¿Cuánto tiene la pirámide de igual base y altura?","حجم منشور 90 سم³. كم حجم الهرم المساوي له قاعدةً وارتفاعًا؟"),options:[r("$270$ cm³"),r("$30$ cm³"),r("$45$ cm³")],correctIndex:1,explanation:a("Piramidea prismaren herena da: $90\\mathbin{:}3=30$.","La pirámide es un tercio del prisma: $90\\mathbin{:}3=30$.","الهرم ثلث المنشور: $90\\mathbin{:}3=30$."),topic:"pyramid-volume"}],la=[{id:1,stage:"polyhedra",prompt:a("Zenbat ertz ditu piramide oktogonal batek?","¿Cuántas aristas tiene una pirámide octogonal?","كم حرفًا للهرم الثماني؟"),expected:o(16),hint:a("Oinarriko ertzak gehi erpinera doazenak.","Las aristas de la base más las que suben al vértice.","أحرف القاعدة مع الأحرف الصاعدة إلى الرأس."),explanation:r("$8+8=2\\cdot 8=16$")},{id:2,stage:"polyhedra",prompt:a("Prisma batek 24 ertz ditu. Zenbat alde ditu oinarriak?","Un prisma tiene 24 aristas. ¿Cuántos lados tiene su base?","لمنشور 24 حرفًا. كم ضلعًا لقاعدته؟"),expected:o(8),hint:a("Prismak $3n$ ertz ditu.","Un prisma tiene $3n$ aristas.","للمنشور $3n$ حرفًا."),explanation:r("$24\\mathbin{:}3=8$")},{id:3,stage:"polyhedra",prompt:a("Poliedro ganbil batek 12 aurpegi eta 30 ertz ditu. Zenbat erpin ditu?","Un poliedro convexo tiene 12 caras y 30 aristas. ¿Cuántos vértices tiene?","متعدد أوجه محدّب له 12 وجهًا و30 حرفًا. كم رأسًا له؟"),expected:o(20),hint:a("Aurpegiak + erpinak = ertzak + 2.","Caras + vértices = aristas + 2.","الأوجه + الرؤوس = الأحرف + 2."),explanation:r("$30+2-12=20$")},{id:4,stage:"polyhedra",prompt:a("Dodekaedroak 12 aurpegi pentagonal ditu, eta erpin bakoitzean 3 aurpegi elkartzen dira. Zenbat erpin ditu?","El dodecaedro tiene 12 caras pentagonales y en cada vértice se juntan 3 caras. ¿Cuántos vértices tiene?","لاثني عشري الأوجه 12 وجهًا خماسيًا، ويلتقي عند كل رأس 3 أوجه. كم رأسًا له؟"),expected:o(20),hint:a("Zenbatu pentagonoen erpin guztiak eta zatitu.","Cuenta todas las esquinas de los pentágonos y divide.","عُدّ جميع زوايا المخمسات ثم اقسم."),explanation:r("$12\\cdot 5\\mathbin{:}3=20$")},{id:5,stage:"areas",prompt:a("Kalkulatu 10 cm-ko ertzeko kubo baten azalera osoa (cm²).","Calcula el área total de un cubo de 10 cm de arista (cm²).","احسب المساحة الكلية لمكعب طول حرفه 10 سم (سم²)."),expected:o(600),hint:a("Sei karratu berdin.","Seis cuadrados iguales.","ستة مربعات متطابقة."),explanation:r("$6\\cdot 10^{2}=600$")},{id:6,stage:"areas",prompt:a("Kalkulatu 5 cm, 4 cm eta 3 cm-ko ortoedro baten azalera osoa (cm²).","Calcula el área total de un ortoedro de 5 cm, 4 cm y 3 cm (cm²).","احسب المساحة الكلية لمتوازي مستطيلات أبعاده 5 سم و4 سم و3 سم (سم²)."),expected:o(94),hint:a("Hiru laukizuzen desberdin, bakoitza bi aldiz.","Tres rectángulos distintos, cada uno dos veces.","ثلاثة مستطيلات مختلفة، كل منها مرتين."),explanation:r("$2\\cdot (5\\cdot 4+5\\cdot 3+4\\cdot 3)=94$")},{id:7,stage:"areas",prompt:a("Piramide erregular baten oinarria 10 cm-ko aldeko karratua da eta apotema 13 cm. Zein da alboko azalera (cm²)?","La base de una pirámide regular es un cuadrado de 10 cm de lado y su apotema mide 13 cm. ¿Cuál es su área lateral (cm²)?","قاعدة هرم منتظم مربع طول ضلعه 10 سم وعامده 13 سم. ما مساحته الجانبية (سم²)؟"),expected:o(260),hint:a("Lau triangelu: oinarria 10, altuera 13.","Cuatro triángulos de base 10 y altura 13.","أربعة مثلثات قاعدتها 10 وارتفاعها 13."),explanation:r("$4\\cdot \\frac{10\\cdot 13}{2}=260$")},{id:8,stage:"areas",prompt:a("Piramide-enbor erregular baten oinarriak 6 cm eta 4 cm-ko aldeko karratuak dira, eta apotema 5 cm. Zein da azalera osoa (cm²)?","Las bases de un tronco de pirámide regular son cuadrados de 6 cm y 4 cm de lado y su apotema mide 5 cm. ¿Cuál es su área total (cm²)?","قاعدتا جذع هرم منتظم مربعان طولا ضلعيهما 6 سم و4 سم وعامده 5 سم. ما مساحته الكلية (سم²)؟"),expected:o(152),hint:a("Lau trapezio gehi bi karratu.","Cuatro trapecios más dos cuadrados.","أربعة أشباه منحرفات مع مربعين."),explanation:r("$4\\cdot \\frac{(6+4)\\cdot 5}{2}=100\\ \\to\\ 100+36+16=152$")},{id:9,stage:"round",prompt:l(a("Zilindro batek 3 cm-ko erradioa eta 10 cm-ko altuera ditu. Zein da alboko azalera (cm²)?","Un cilindro tiene 3 cm de radio y 10 cm de altura. ¿Cuál es su área lateral (cm²)?","أسطوانة نصف قطرها 3 سم وارتفاعها 10 سم. ما مساحتها الجانبية (سم²)؟"),s),expected:d("188,4"),hint:a("Laukizuzena: $2\\pi r$ bider $h$.","El rectángulo: $2\\pi r$ por $h$.","المستطيل: $2\\pi r$ في $h$."),explanation:r("$2\\cdot 3{,}14\\cdot 3\\cdot 10=188{,}4$")},{id:10,stage:"round",prompt:l(a("Kono baten erradioa 3 cm da eta sortzailea 5 cm. Zein da alboko azalera (cm²)?","Un cono tiene 3 cm de radio y 5 cm de generatriz. ¿Cuál es su área lateral (cm²)?","مخروط نصف قطره 3 سم وراسمه 5 سم. ما مساحته الجانبية (سم²)؟"),s),expected:d("47,1"),hint:a("$\\pi r g$.","$\\pi r g$.","$\\pi r g$."),explanation:r("$3{,}14\\cdot 3\\cdot 5=47{,}1$")},{id:11,stage:"round",prompt:l(a("Kalkulatu 5 cm-ko erradioko esfera baten azalera (cm²).","Calcula el área de una esfera de 5 cm de radio (cm²).","احسب مساحة كرة نصف قطرها 5 سم (سم²)."),s),expected:o(314),hint:a("Lau zirkulu handi.","Cuatro círculos máximos.","أربع دوائر عظمى."),explanation:r("$4\\cdot 3{,}14\\cdot 5^{2}=314$")},{id:12,stage:"round",prompt:a("Kono baten erradioa 5 cm da eta altuera 12 cm. Zenbat da sortzailea?","Un cono tiene 5 cm de radio y 12 cm de altura. ¿Cuánto mide la generatriz?","مخروط نصف قطره 5 سم وارتفاعه 12 سم. كم طول راسمه؟"),expected:o(13),hint:a("Sortzailea hipotenusa da.","La generatriz es la hipotenusa.","الراسم هو الوتر."),explanation:r("$\\sqrt{12^{2}+5^{2}}=\\sqrt{169}=13$")},{id:13,stage:"units",prompt:a("Adierazi 3,5 m³ dm³-tan.","Expresa 3,5 m³ en dm³.","عبّر عن 3.5 م³ بالديسيمتر المكعب."),expected:o(3500),hint:a("Maila bat jaitsi: bider 1000.","Baja un escalón: por 1000.","انزل درجة: في 1000."),explanation:r("$3{,}5\\cdot 1000=3500$")},{id:14,stage:"units",prompt:a("Adierazi 42 000 cm³ dm³-tan.","Expresa 42 000 cm³ en dm³.","عبّر عن 42000 سم³ بالديسيمتر المكعب."),expected:o(42),hint:a("Maila bat igo: zati 1000.","Sube un escalón: entre 1000.","اصعد درجة: على 1000."),explanation:r("$42\\,000\\mathbin{:}1000=42$")},{id:15,stage:"units",prompt:a("Zenbat cm³ dira 2,5 L?","¿Cuántos cm³ son 2,5 L?","كم سم³ في 2.5 لتر؟"),expected:o(2500),hint:a("1 L = 1 dm³ = 1000 cm³.","1 L = 1 dm³ = 1000 cm³.","1 L = 1 dm³ = 1000 cm³."),explanation:r("$2{,}5\\cdot 1000=2500$")},{id:16,stage:"units",prompt:a("Kalkulatu 8 cm × 5 cm × 3 cm-ko ortoedro baten bolumena (cm³).","Calcula el volumen de un ortoedro de 8 cm × 5 cm × 3 cm (cm³).","احسب حجم متوازي مستطيلات أبعاده 8 سم × 5 سم × 3 سم (سم³)."),expected:o(120),hint:a("Biderkatu hiru neurriak.","Multiplica las tres medidas.","اضرب الأبعاد الثلاثة."),explanation:r("$8\\cdot 5\\cdot 3=120$")},{id:17,stage:"volume",prompt:a("Prisma baten oinarria 6 cm eta 8 cm-ko katetoak dituen triangelu angeluzuzena da, eta altuera 10 cm. Zein da bolumena (cm³)?","La base de un prisma es un triángulo rectángulo de catetos 6 cm y 8 cm y su altura mide 10 cm. ¿Cuál es su volumen (cm³)?","قاعدة منشور مثلث قائم ضلعاه القائمان 6 سم و8 سم وارتفاعه 10 سم. ما حجمه (سم³)؟"),expected:o(240),hint:a("Oinarriaren azalera bider altuera.","Área de la base por altura.","مساحة القاعدة في الارتفاع."),explanation:r("$\\frac{6\\cdot 8}{2}\\cdot 10=240$")},{id:18,stage:"volume",prompt:l(a("Zilindro batek 2 cm-ko erradioa eta 5 cm-ko altuera ditu. Zein da bolumena (cm³)?","Un cilindro tiene 2 cm de radio y 5 cm de altura. ¿Cuál es su volumen (cm³)?","أسطوانة نصف قطرها 2 سم وارتفاعها 5 سم. ما حجمها (سم³)؟"),s),expected:d("62,8"),hint:a("$\\pi r^{2}h$.","$\\pi r^{2}h$.","$\\pi r^{2}h$."),explanation:r("$3{,}14\\cdot 2^{2}\\cdot 5=62{,}8$")},{id:19,stage:"volume",prompt:a("Piramide baten oinarria 9 cm-ko aldeko karratua da eta altuera 10 cm. Zein da bolumena (cm³)?","La base de una pirámide es un cuadrado de 9 cm de lado y su altura mide 10 cm. ¿Cuál es su volumen (cm³)?","قاعدة هرم مربع طول ضلعه 9 سم وارتفاعه 10 سم. ما حجمه (سم³)؟"),expected:o(270),hint:a("Prismaren herena.","Un tercio del prisma.","ثلث المنشور."),explanation:r("$\\frac{9^{2}\\cdot 10}{3}=270$")},{id:20,stage:"volume",prompt:l(a("Kalkulatu 6 cm-ko erradioko esfera baten bolumena (cm³).","Calcula el volumen de una esfera de 6 cm de radio (cm³).","احسب حجم كرة نصف قطرها 6 سم (سم³)."),s),expected:d("904,32"),hint:a("$\\frac{4}{3}\\pi r^{3}$, eta $6^{3}=216$.","$\\frac{4}{3}\\pi r^{3}$, y $6^{3}=216$.","$\\frac{4}{3}\\pi r^{3}$، و$6^{3}=216$."),explanation:r("$\\frac{4\\cdot 3{,}14\\cdot 6^{3}}{3}=904{,}32$")}],sa=[{id:101,stage:"polyhedra",points:10,context:"starter",prompt:a("Piramide batek 7 erpin ditu. Zenbat ertz ditu?","Una pirámide tiene 7 vértices. ¿Cuántas aristas tiene?","لهرم 7 رؤوس. كم حرفًا له؟"),expected:o(12),hint:a("Erpin bat goian dago; besteak oinarrian.","Un vértice está arriba; los demás en la base.","رأس واحد في الأعلى؛ والباقي في القاعدة."),explanation:r("$7-1=6\\ \\to\\ 2\\cdot 6=12$")},{id:102,stage:"polyhedra",points:20,context:"advanced",prompt:a("Prisma batek 30 erpin ditu. Zenbat aurpegi ditu?","Un prisma tiene 30 vértices. ¿Cuántas caras tiene?","لمنشور 30 رأسًا. كم وجهًا له؟"),expected:o(17),hint:a("Erpinen erdiak oinarri bakoitzean.","La mitad de los vértices en cada base.","نصف الرؤوس في كل قاعدة."),explanation:r("$30\\mathbin{:}2=15\\ \\to\\ 15+2=17$")},{id:103,stage:"polyhedra",points:30,context:"master",prompt:a("Poliedro ganbil baten aurpegi guztiak triangeluak dira eta 12 ertz ditu. Zenbat aurpegi ditu?","Todas las caras de un poliedro convexo son triángulos y tiene 12 aristas. ¿Cuántas caras tiene?","جميع أوجه متعدد أوجه محدّب مثلثات وله 12 حرفًا. كم وجهًا له؟"),expected:o(8),hint:a("Triangelu bakoitzak 3 alde ditu, eta ertz bakoitza bi aurpegirena da.","Cada triángulo tiene 3 lados y cada arista es de dos caras.","لكل مثلث 3 أضلاع وكل حرف مشترك بين وجهين."),explanation:r("$2\\cdot 12\\mathbin{:}3=8$")},{id:104,stage:"areas",points:10,context:"starter",prompt:a("Kubo baten azalera osoa 150 dm² da. Zenbat da ertza (dm)?","El área total de un cubo es 150 dm². ¿Cuánto mide su arista (dm)?","المساحة الكلية لمكعب 150 دسم². كم طول حرفه (دسم)؟"),expected:o(5),hint:a("Aurpegi bat: zatitu 6z.","Una cara: divide entre 6.","وجه واحد: اقسم على 6."),explanation:r("$150\\mathbin{:}6=25\\ \\to\\ \\sqrt{25}=5$")},{id:105,stage:"areas",points:20,context:"advanced",prompt:a("Kaxa ortoedriko batek 9 dm luze eta 6 dm zabal ditu, eta azalera osoa 228 dm² da. Zenbat da altuera (dm)?","Una caja ortoédrica mide 9 dm de largo y 6 dm de ancho, y su área total es 228 dm². ¿Cuánto mide su altura (dm)?","صندوق على شكل متوازي مستطيلات طوله 9 دسم وعرضه 6 دسم ومساحته الكلية 228 دسم². كم ارتفاعه (دسم)؟"),expected:o(4),hint:a("Oinarriak: $2\\cdot 9\\cdot 6=108$. Alboak: $2\\cdot (9+6)\\cdot h=30h$.","Bases: $2\\cdot 9\\cdot 6=108$. Laterales: $2\\cdot (9+6)\\cdot h=30h$.","القاعدتان: $2\\cdot 9\\cdot 6=108$. الجوانب: $2\\cdot (9+6)\\cdot h=30h$."),explanation:r("$(228-108)\\mathbin{:}30=4$")},{id:106,stage:"areas",points:30,context:"master",prompt:a("Prisma zuzen baten oinarriak 16 cm eta 12 cm-ko diagonalak dituzten erronboak dira, eta altuera 15 cm. Kalkulatu azalera osoa (cm²).","Las bases de un prisma recto son rombos de diagonales 16 cm y 12 cm, y su altura mide 15 cm. Calcula su área total (cm²).","قاعدتا منشور قائم معيّنان قطراهما 16 سم و12 سم، وارتفاعه 15 سم. احسب مساحته الكلية (سم²)."),expected:o(792),hint:a("Erronboaren aldea Pitagorasekin, diagonal-erdiekin.","El lado del rombo con Pitágoras, con las semidiagonales.","ضلع المعيّن بفيثاغورس بنصفي القطرين."),explanation:r("$\\sqrt{8^{2}+6^{2}}=10\\ \\to\\ 4\\cdot 10\\cdot 15+2\\cdot \\frac{16\\cdot 12}{2}=792$")},{id:107,stage:"round",points:10,context:"starter",prompt:l(a("Goian irekita dagoen aljibe zilindriko baten erradioa 4 m da eta altuera 5 m. Zenbat m² iragazgaiztu behar dira (hondoa eta hormak)?","Un aljibe cilíndrico abierto por arriba tiene 4 m de radio y 5 m de altura. ¿Cuántos m² hay que impermeabilizar (suelo y paredes)?","خزان أسطواني مفتوح من الأعلى نصف قطره 4 م وارتفاعه 5 م. كم م² يجب عزلها (الأرضية والجدران)؟"),s),expected:d("175,84"),hint:a("Oinarri bakarra.","Una sola base.","قاعدة واحدة فقط."),explanation:r("$2\\cdot 3{,}14\\cdot 4\\cdot 5+3{,}14\\cdot 4^{2}=175{,}84$")},{id:108,stage:"round",points:20,context:"advanced",prompt:l(a("Lorontzi batek kono-enbor forma du: oinarrien erradioak 14 cm eta 20 cm, sortzailea 38 cm. Zein da kanpoko alboko azalera (cm²)?","Un macetero tiene forma de tronco de cono: radios de las bases 14 cm y 20 cm, generatriz 38 cm. ¿Cuál es su área lateral exterior (cm²)?","أصيص على شكل جذع مخروط: نصفا قطري قاعدتيه 14 سم و20 سم وراسمه 38 سم. ما مساحته الجانبية الخارجية (سم²)؟"),s),expected:d("4056,88"),hint:a("$\\pi (R+r)\\,g$.","$\\pi (R+r)\\,g$.","$\\pi (R+r)\\,g$."),explanation:r("$3{,}14\\cdot (20+14)\\cdot 38=4056{,}88$")},{id:109,stage:"round",points:30,context:"master",prompt:l(a("10 cm-ko erradioko esfera bat zentrotik 6 cm-ra dagoen plano batek mozten du. Zein da sekzioaren azalera (cm²)?","Un plano corta una esfera de 10 cm de radio a 6 cm del centro. ¿Cuál es el área de la sección (cm²)?","يقطع مستوٍ كرةً نصف قطرها 10 سم على بعد 6 سم من المركز. ما مساحة المقطع (سم²)؟"),s),expected:d("200,96"),hint:a("Sekzioaren erradioa: katetoa, esferaren erradioa hipotenusa izanik.","Radio de la sección: un cateto, con el radio de la esfera como hipotenusa.","نصف قطر المقطع: ضلع قائم ونصف قطر الكرة هو الوتر."),explanation:r("$\\sqrt{10^{2}-6^{2}}=8\\ \\to\\ 3{,}14\\cdot 8^{2}=200{,}96$")},{id:110,stage:"units",points:10,context:"starter",prompt:a("Ur-depositu batek 2,4 m³ ditu. Zenbat litro dira?","Un depósito de agua tiene 2,4 m³. ¿Cuántos litros son?","خزان ماء حجمه 2.4 م³. كم لترًا؟"),expected:o(2400),hint:a("1 m³ = 1000 L.","1 m³ = 1000 L.","1 m³ = 1000 L."),explanation:r("$2{,}4\\cdot 1000=2400$")},{id:111,stage:"units",points:20,context:"advanced",prompt:a("Ekaitz batean 35 L/m² erori dira. 200 m²-ko teilatu batek ura biltzen du. Zenbat m³ bildu dira?","En una tormenta han caído 35 L/m². Un tejado de 200 m² recoge el agua. ¿Cuántos m³ se han recogido?","هطل في عاصفة 35 لترًا لكل م². سطح مساحته 200 م² يجمع الماء. كم م³ جُمع؟"),expected:o(7),hint:a("Lehenik litroak; gero 1000 L = 1 m³.","Primero los litros; luego 1000 L = 1 m³.","أولًا اللترات؛ ثم 1000 L = 1 m³."),explanation:r("$35\\cdot 200=7000\\ \\to\\ 7000\\mathbin{:}1000=7$")},{id:112,stage:"units",points:30,context:"master",prompt:a("Akuario batek 60 cm × 30 cm × 40 cm neurtzen ditu eta hiru laurden beteta dago. Zenbat litro ur ditu?","Un acuario mide 60 cm × 30 cm × 40 cm y está lleno en sus tres cuartas partes. ¿Cuántos litros de agua tiene?","حوض سمك أبعاده 60 سم × 30 سم × 40 سم مملوء ثلاثة أرباعه. كم لترًا من الماء فيه؟"),expected:o(54),hint:a("cm³-tik L-ra: zati 1000.","De cm³ a L: entre 1000.","من cm³ إلى L: على 1000."),explanation:r("$60\\cdot 30\\cdot 40=72\\,000\\ \\to\\ \\frac{3}{4}\\cdot 72=54$")},{id:113,stage:"volume",points:10,context:"starter",prompt:l(a("Kono baten erradioa 3 cm da eta altuera 4 cm. Zein da bolumena (cm³)?","Un cono tiene 3 cm de radio y 4 cm de altura. ¿Cuál es su volumen (cm³)?","مخروط نصف قطره 3 سم وارتفاعه 4 سم. ما حجمه (سم³)؟"),s),expected:d("37,68"),hint:a("Zilindroaren herena.","Un tercio del cilindro.","ثلث الأسطوانة."),explanation:r("$\\frac{3{,}14\\cdot 3^{2}\\cdot 4}{3}=37{,}68$")},{id:114,stage:"volume",points:20,context:"advanced",prompt:l(a("30 cm × 30 cm × 10 cm-ko kaxa batean 3 cm-ko erradioko 20 bola sartu dira. Zenbat cm³ geratzen dira hutsik?","En una caja de 30 cm × 30 cm × 10 cm se han metido 20 bolas de 3 cm de radio. ¿Cuántos cm³ quedan vacíos?","وُضعت 20 كرة نصف قطر كل منها 3 سم في صندوق أبعاده 30 سم × 30 سم × 10 سم. كم سم³ يبقى فارغًا؟"),s),expected:d("6739,2"),hint:a("Bola bakoitza: $\\frac{4}{3}\\pi\\cdot 27$.","Cada bola: $\\frac{4}{3}\\pi\\cdot 27$.","كل كرة: $\\frac{4}{3}\\pi\\cdot 27$."),explanation:r("$\\frac{4\\cdot 3{,}14\\cdot 27}{3}=113{,}04\\ \\to\\ 9000-20\\cdot 113{,}04=6739{,}2$")},{id:115,stage:"volume",points:30,context:"master",prompt:a("12 cm-ko aldeko oinarri karratua eta 12 cm-ko altuera dituen piramide bat altueraren erdian mozten da. Zein da enborraren bolumena (cm³)?","Una pirámide de base cuadrada de 12 cm de lado y 12 cm de altura se corta a mitad de su altura. ¿Cuál es el volumen del tronco (cm³)?","هرم قاعدته مربع طول ضلعه 12 سم وارتفاعه 12 سم يُقطع عند منتصف ارتفاعه. ما حجم الجذع (سم³)؟"),expected:o(504),hint:a("Piramide txikiak erdiko aldea eta erdiko altuera ditu.","La pirámide pequeña tiene la mitad de lado y la mitad de altura.","للهرم الصغير نصف الضلع ونصف الارتفاع."),explanation:r("$\\frac{12^{2}\\cdot 12}{3}-\\frac{6^{2}\\cdot 6}{3}=504$")}],ua=[{id:"polyhedra",title:a("Poliedroak","Poliedros","متعددات الأوجه"),items:[{id:1,difficulty:"easy",question:a("Zenbat aurpegi, ertz eta erpin ditu prisma heptagonal batek?","¿Cuántas caras, aristas y vértices tiene un prisma heptagonal?","كم وجهًا وحرفًا ورأسًا للمنشور السباعي؟"),solution:r("$7+2=9\\qquad 3\\cdot 7=21\\qquad 2\\cdot 7=14$")},{id:2,difficulty:"easy",question:a("Zenbat ertz ditu piramide pentagonal batek?","¿Cuántas aristas tiene una pirámide pentagonal?","كم حرفًا للهرم الخماسي؟"),solution:r("$2\\cdot 5=10$"),answer:{expected:o(10)}},{id:3,difficulty:"easy",question:a("Egiaztatu Eulerren formula prisma triangeluar batean.","Comprueba la fórmula de Euler en un prisma triangular.","تحقّق من صيغة أويلر في منشور ثلاثي."),solution:a("5 aurpegi, 6 erpin, 9 ertz: $5+6=9+2$.","5 caras, 6 vértices, 9 aristas: $5+6=9+2$.","5 أوجه و6 رؤوس و9 أحرف: $5+6=9+2$.")},{id:4,difficulty:"medium",question:a("Prisma batek 18 ertz ditu. Zenbat alde ditu oinarriak?","Un prisma tiene 18 aristas. ¿Cuántos lados tiene su base?","لمنشور 18 حرفًا. كم ضلعًا لقاعدته؟"),solution:a("$18\\mathbin{:}3=6$: prisma hexagonala.","$18\\mathbin{:}3=6$: prisma hexagonal.","$18\\mathbin{:}3=6$: منشور سداسي."),answer:{expected:o(6)}},{id:5,difficulty:"medium",question:a("Poliedro ganbil batek 10 erpin eta 15 ertz ditu. Zenbat aurpegi ditu?","Un poliedro convexo tiene 10 vértices y 15 aristas. ¿Cuántas caras tiene?","متعدد أوجه محدّب له 10 رؤوس و15 حرفًا. كم وجهًا له؟"),solution:r("$15+2-10=7$"),answer:{expected:o(7)}},{id:6,difficulty:"medium",question:a("Piramide batek 11 aurpegi ditu. Zenbat erpin ditu?","Una pirámide tiene 11 caras. ¿Cuántos vértices tiene?","لهرم 11 وجهًا. كم رأسًا له؟"),solution:a("Oinarriak 10 alde ditu: $11-1=10\\ \\to\\ 10+1=11$.","La base tiene 10 lados: $11-1=10\\ \\to\\ 10+1=11$.","للقاعدة 10 أضلاع: $11-1=10\\ \\to\\ 10+1=11$."),answer:{expected:o(11)}},{id:7,difficulty:"medium",question:a("Zergatik ezin da hexagono erregularrekin poliedro erregularrik egin?","¿Por qué no se puede construir un poliedro regular con hexágonos regulares?","لماذا لا يمكن بناء متعدد أوجه منتظم من مسدسات منتظمة؟"),solution:a("Hexagonoaren angelua 120° da; hiru hexagono erpin batean: $3\\cdot 120=360$, laua geratzen da.","El ángulo del hexágono mide 120°; tres hexágonos en un vértice: $3\\cdot 120=360$, queda plano.","زاوية المسدس 120°؛ ثلاثة مسدسات عند رأس: $3\\cdot 120=360$، فيبقى مستويًا.")},{id:8,difficulty:"hard",question:a("Ikosaedroak 20 triangelu ditu eta erpin bakoitzean 5 aurpegi elkartzen dira. Zenbat erpin ditu?","El icosaedro tiene 20 triángulos y en cada vértice se juntan 5 caras. ¿Cuántos vértices tiene?","لعشريني الأوجه 20 مثلثًا ويلتقي عند كل رأس 5 أوجه. كم رأسًا له؟"),solution:r("$20\\cdot 3\\mathbin{:}5=12$"),answer:{expected:o(12)}},{id:9,difficulty:"hard",question:a("1 dm-ko ertzeko dodekaedro baten hezurdura alanbrez egin nahi dugu. Zenbat dm alanbre behar dira?","Queremos hacer el esqueleto de un dodecaedro de 1 dm de arista con alambre. ¿Cuántos dm de alambre hacen falta?","نريد صنع هيكل اثني عشري أوجه طول حرفه 1 دسم من السلك. كم دسم من السلك يلزم؟"),solution:a("Ertzak: $12\\cdot 5\\mathbin{:}2=30$, beraz 30 dm.","Aristas: $12\\cdot 5\\mathbin{:}2=30$, así que 30 dm.","الأحرف: $12\\cdot 5\\mathbin{:}2=30$، إذن 30 دسم."),answer:{expected:o(30)}},{id:10,difficulty:"hard",question:a("Bi tetraedro oinarritik itsatsiz, sei triangelu aldeberdineko poliedro bat lortzen da. Erregularra da?","Pegando dos tetraedros por una cara se obtiene un poliedro de seis triángulos equiláteros. ¿Es regular?","بلصق رباعيي أوجه من وجه نحصل على متعدد أوجه من ستة مثلثات متساوية الأضلاع. هل هو منتظم؟"),solution:a("Ez: erpin batzuetan 3 aurpegi elkartzen dira eta beste batzuetan 4. Euler betetzen da: $6+5=9+2$.","No: en unos vértices se juntan 3 caras y en otros 4. Euler se cumple: $6+5=9+2$.","لا: يلتقي عند بعض الرؤوس 3 أوجه وعند أخرى 4. وتتحقق صيغة أويلر: $6+5=9+2$.")}]},{id:"areas",title:a("Poliedroen azalerak","Áreas de poliedros","مساحات متعددات الأوجه"),items:[{id:11,difficulty:"easy",question:a("Kalkulatu 4 cm-ko ertzeko kubo baten azalera osoa (cm²).","Calcula el área total de un cubo de 4 cm de arista (cm²).","احسب المساحة الكلية لمكعب طول حرفه 4 سم (سم²)."),solution:r("$6\\cdot 4^{2}=96$"),answer:{expected:o(96)}},{id:12,difficulty:"easy",question:a("Kalkulatu 6 cm, 4 cm eta 2 cm-ko ortoedro baten azalera osoa (cm²).","Calcula el área total de un ortoedro de 6 cm, 4 cm y 2 cm (cm²).","احسب المساحة الكلية لمتوازي مستطيلات أبعاده 6 سم و4 سم و2 سم (سم²)."),solution:r("$2\\cdot (6\\cdot 4+6\\cdot 2+4\\cdot 2)=88$"),answer:{expected:o(88)}},{id:13,difficulty:"easy",question:a("Prisma baten oinarriaren perimetroa 18 cm da eta altuera 7 cm. Zein da alboko azalera (cm²)?","El perímetro de la base de un prisma mide 18 cm y su altura 7 cm. ¿Cuál es su área lateral (cm²)?","محيط قاعدة منشور 18 سم وارتفاعه 7 سم. ما مساحته الجانبية (سم²)؟"),solution:r("$18\\cdot 7=126$"),answer:{expected:o(126)}},{id:14,difficulty:"medium",question:a("Piramide erregular baten oinarria 8 cm-ko aldeko karratua da eta apotema 10 cm. Kalkulatu azalera osoa (cm²).","La base de una pirámide regular es un cuadrado de 8 cm de lado y su apotema mide 10 cm. Calcula su área total (cm²).","قاعدة هرم منتظم مربع طول ضلعه 8 سم وعامده 10 سم. احسب مساحته الكلية (سم²)."),solution:r("$4\\cdot \\frac{8\\cdot 10}{2}+8^{2}=224$"),answer:{expected:o(224)}},{id:15,difficulty:"medium",question:a("Piramide erregular baten oinarria 16 cm-ko aldeko karratua da eta altuera 6 cm. Kalkulatu azalera osoa (cm²).","La base de una pirámide regular es un cuadrado de 16 cm de lado y su altura mide 6 cm. Calcula su área total (cm²).","قاعدة هرم منتظم مربع طول ضلعه 16 سم وارتفاعه 6 سم. احسب مساحته الكلية (سم²)."),solution:r("$\\sqrt{6^{2}+8^{2}}=10\\ \\to\\ 4\\cdot \\frac{16\\cdot 10}{2}+16^{2}=576$"),answer:{expected:o(576)}},{id:16,difficulty:"medium",question:a("Prisma hexagonal erregular baten oinarriko ertzak 2 cm dira (apotema 1,73 cm) eta alboko ertzak 4 cm. Kalkulatu azalera osoa (cm²).","Un prisma hexagonal regular tiene aristas de la base de 2 cm (apotema 1,73 cm) y aristas laterales de 4 cm. Calcula su área total (cm²).","منشور سداسي منتظم أحرف قاعدته 2 سم (العامد 1.73 سم) وأحرفه الجانبية 4 سم. احسب مساحته الكلية (سم²)."),solution:r("$2\\cdot \\frac{12\\cdot 1{,}73}{2}+12\\cdot 4=68{,}76$"),answer:{expected:d("68,76")}},{id:17,difficulty:"medium",question:a("0,6 m × 0,5 m × 0,4 m-ko kaxa bat txapaz forratu nahi da, 18 €/m². Zenbat kostatuko da (€)?","Queremos forrar con chapa un cajón de 0,6 m × 0,5 m × 0,4 m, a 18 €/m². ¿Cuánto costará (€)?","نريد تغليف صندوق أبعاده 0.6 م × 0.5 م × 0.4 م بالصفيح بسعر 18 €/م². كم سيكلف (€)؟"),solution:r("$2\\cdot (0{,}3+0{,}2+0{,}24)=1{,}48\\ \\to\\ 1{,}48\\cdot 18=26{,}64$"),answer:{expected:d("26,64")}},{id:18,difficulty:"hard",question:l(a("Piramide-enbor karratu erregular baten oinarrietako ertzak 4 cm eta 2 cm dira, eta alboko ertzak 5 cm. Kalkulatu azalera osoa (cm²), apotema hamarrenetara hurbilduta.","Un tronco de pirámide cuadrangular regular tiene aristas de las bases de 4 cm y 2 cm y aristas laterales de 5 cm. Calcula su área total (cm²), con la apotema aproximada a las décimas.","جذع هرم رباعي منتظم أحرف قاعدتيه 4 سم و2 سم وأحرفه الجانبية 5 سم. احسب مساحته الكلية (سم²) مع تقريب العامد إلى الأعشار.")),solution:r("$\\sqrt{5^{2}-1^{2}}\\approx 4{,}9\\ \\to\\ 4\\cdot \\frac{(4+2)\\cdot 4{,}9}{2}+16+4=78{,}8$"),answer:{expected:d("78,8")}},{id:19,difficulty:"hard",question:a("Piramide hexagonal erregular baten oinarriko ertzak 10 cm dira eta alboko ertzak 13 cm. Zein da alboko azalera (cm²)?","Una pirámide hexagonal regular tiene aristas de la base de 10 cm y aristas laterales de 13 cm. ¿Cuál es su área lateral (cm²)?","هرم سداسي منتظم أحرف قاعدته 10 سم وأحرفه الجانبية 13 سم. ما مساحته الجانبية (سم²)؟"),solution:r("$\\sqrt{13^{2}-5^{2}}=12\\ \\to\\ 6\\cdot \\frac{10\\cdot 12}{2}=360$"),answer:{expected:o(360)}},{id:20,difficulty:"hard",question:l(a("Kubo baten azalera osoa 150 dm² da. Kalkulatu haren diagonala (dm).","El área total de un cubo es 150 dm². Calcula su diagonal (dm).","المساحة الكلية لمكعب 150 دسم². احسب قطره (دسم)."),$),solution:a("Ertza 5 da: $\\sqrt{25+25+25}=\\sqrt{75}\\approx 8{,}66$.","La arista mide 5: $\\sqrt{25+25+25}=\\sqrt{75}\\approx 8{,}66$.","طول الحرف 5: $\\sqrt{25+25+25}=\\sqrt{75}\\approx 8{,}66$."),answer:{expected:d("8,66")}}]},{id:"round",title:a("Biraketa-gorputzak","Cuerpos de revolución","الأجسام الدورانية"),items:[{id:21,difficulty:"easy",question:l(a("Zilindro batek 1 m-ko erradioa eta 4 m-ko altuera ditu. Kalkulatu alboko azalera (m²).","Un cilindro tiene 1 m de radio y 4 m de altura. Calcula su área lateral (m²).","أسطوانة نصف قطرها 1 م وارتفاعها 4 م. احسب مساحتها الجانبية (م²)."),s),solution:r("$2\\cdot 3{,}14\\cdot 1\\cdot 4=25{,}12$"),answer:{expected:d("25,12")}},{id:22,difficulty:"easy",question:l(a("Kalkulatu 2 cm-ko erradioko esfera baten azalera (cm²).","Calcula el área de una esfera de 2 cm de radio (cm²).","احسب مساحة كرة نصف قطرها 2 سم (سم²)."),s),solution:r("$4\\cdot 3{,}14\\cdot 2^{2}=50{,}24$"),answer:{expected:d("50,24")}},{id:23,difficulty:"easy",question:a("Zer gorputz sortzen da triangelu angeluzuzen bat kateto baten inguruan biratzean? Eta zirkulu-erdi bat diametroaren inguruan?","¿Qué cuerpo se genera al girar un triángulo rectángulo alrededor de un cateto? ¿Y un semicírculo alrededor de su diámetro?","ما الجسم الناتج عن دوران مثلث قائم حول أحد ضلعيه القائمين؟ ونصف دائرة حول قطرها؟"),solution:a("Konoa; esfera.","Un cono; una esfera.","مخروط؛ كرة.")},{id:24,difficulty:"medium",question:l(a("Kono baten erradioa 5 cm da eta sortzailea 15 cm. Kalkulatu azalera osoa (cm²).","Un cono tiene 5 cm de radio y 15 cm de generatriz. Calcula su área total (cm²).","مخروط نصف قطره 5 سم وراسمه 15 سم. احسب مساحته الكلية (سم²)."),s),solution:r("$3{,}14\\cdot 5\\cdot 15+3{,}14\\cdot 5^{2}=314$"),answer:{expected:o(314)}},{id:25,difficulty:"medium",question:l(a("Kono baten altuera 16 cm da eta erradioa 12 cm. Kalkulatu alboko azalera (cm²).","Un cono tiene 16 cm de altura y 12 cm de radio. Calcula su área lateral (cm²).","مخروط ارتفاعه 16 سم ونصف قطره 12 سم. احسب مساحته الجانبية (سم²)."),s),solution:r("$\\sqrt{16^{2}+12^{2}}=20\\ \\to\\ 3{,}14\\cdot 12\\cdot 20=753{,}6$"),answer:{expected:d("753,6")}},{id:26,difficulty:"medium",question:l(a("12 m sakoneko eta 1,6 m diametroko putzu baten hormak zementuz estali dira, 40 €/m². Zenbat kostatu da (€)?","Las paredes de un pozo de 12 m de profundidad y 1,6 m de diámetro se han cubierto de cemento a 40 €/m². ¿Cuánto ha costado (€)?","غُطّيت جدران بئر عمقها 12 م وقطرها 1.6 م بالإسمنت بسعر 40 €/م². كم كلّف ذلك (€)؟"),s),solution:r("$2\\cdot 3{,}14\\cdot 0{,}8\\cdot 12=60{,}288\\ \\to\\ 60{,}288\\cdot 40=2411{,}52$"),answer:{expected:d("2411,52")}},{id:27,difficulty:"medium",question:l(a("10 dm-ko diametroko esfera batean, zein da 4 dm-ko altuerako zona esferiko baten azalera (dm²)?","En una esfera de 10 dm de diámetro, ¿cuál es el área de una zona esférica de 4 dm de altura (dm²)?","في كرة قطرها 10 دسم، ما مساحة منطقة كروية ارتفاعها 4 دسم (دسم²)؟"),s),solution:r("$2\\cdot 3{,}14\\cdot 5\\cdot 4=125{,}6$"),answer:{expected:d("125,6")}},{id:28,difficulty:"hard",question:l(a("Kono-enbor baten oinarrien erradioak 22 cm eta 17 cm dira, eta altuera 12 cm. Kalkulatu azalera osoa (cm²).","Un tronco de cono tiene radios de las bases de 22 cm y 17 cm y 12 cm de altura. Calcula su área total (cm²).","جذع مخروط نصفا قطري قاعدتيه 22 سم و17 سم وارتفاعه 12 سم. احسب مساحته الكلية (سم²)."),s),solution:r("$\\sqrt{12^{2}+5^{2}}=13\\ \\to\\ 3{,}14\\cdot 39\\cdot 13+3{,}14\\cdot 22^{2}+3{,}14\\cdot 17^{2}=4019{,}2$"),answer:{expected:d("4019,2")}},{id:29,difficulty:"hard",question:l(a("Kono baten alboko garapena 12 cm-ko erradioko zirkulu-erdia da. Zenbat da konoaren altuera (cm)?","El desarrollo lateral de un cono es un semicírculo de 12 cm de radio. ¿Cuánto mide la altura del cono (cm)?","النشر الجانبي لمخروط نصف دائرة نصف قطرها 12 سم. كم ارتفاع المخروط (سم)؟"),$),solution:a("Arkua oinarriaren zirkunferentzia da: $2\\pi r=12\\pi$, beraz $r=6$. Altuera: $\\sqrt{12^{2}-6^{2}}=\\sqrt{108}\\approx 10{,}39$.","El arco es la circunferencia de la base: $2\\pi r=12\\pi$, así que $r=6$. Altura: $\\sqrt{12^{2}-6^{2}}=\\sqrt{108}\\approx 10{,}39$.","القوس هو محيط القاعدة: $2\\pi r=12\\pi$، إذن $r=6$. الارتفاع: $\\sqrt{12^{2}-6^{2}}=\\sqrt{108}\\approx 10{,}39$."),answer:{expected:d("10,39")}},{id:30,difficulty:"hard",question:a("12 cm-ko diametroko esfera bat zentrotik 3,6 cm-ra dagoen plano batek mozten du. Zenbat da sekzioaren erradioa (cm)?","Un plano corta una esfera de 12 cm de diámetro a 3,6 cm del centro. ¿Cuánto mide el radio de la sección (cm)?","يقطع مستوٍ كرةً قطرها 12 سم على بعد 3.6 سم من المركز. كم نصف قطر المقطع (سم)؟"),solution:r("$\\sqrt{6^{2}-3{,}6^{2}}=\\sqrt{23{,}04}=4{,}8$"),answer:{expected:d("4,8")}}]},{id:"units",title:a("Bolumena eta edukiera","Volumen y capacidad","الحجم والسعة"),items:[{id:31,difficulty:"easy",question:a("Adierazi 4 m³ dm³-tan.","Expresa 4 m³ en dm³.","عبّر عن 4 م³ بالديسيمتر المكعب."),solution:r("$4\\cdot 1000=4000$"),answer:{expected:o(4e3)}},{id:32,difficulty:"easy",question:a("Zenbat litro dira 7500 cm³?","¿Cuántos litros son 7500 cm³?","كم لترًا في 7500 سم³؟"),solution:r("$7500\\mathbin{:}1000=7{,}5$"),answer:{expected:d("7,5")}},{id:33,difficulty:"easy",question:a("Zenbat cm³ dira 250 mL?","¿Cuántos cm³ son 250 mL?","كم سم³ في 250 مل؟"),solution:a("1 mL = 1 cm³: 250 cm³.","1 mL = 1 cm³: 250 cm³.","1 mL = 1 cm³: 250 سم³."),answer:{expected:o(250)}},{id:34,difficulty:"medium",question:a("Zenbat litro dira 0,045 m³?","¿Cuántos litros son 0,045 m³?","كم لترًا في 0.045 م³؟"),solution:r("$0{,}045\\cdot 1000=45$"),answer:{expected:o(45)}},{id:35,difficulty:"medium",question:a("Adierazi 3 m³ 25 dm³ dm³-tan.","Expresa 3 m³ 25 dm³ en dm³.","عبّر عن 3 م³ و25 دسم³ بالديسيمتر المكعب."),solution:r("$3\\cdot 1000+25=3025$"),answer:{expected:o(3025)}},{id:36,difficulty:"medium",question:a("2 m-ko ertzeko depositu kubiko bat urez betetzen da. Zenbat litro sartzen dira?","Se llena de agua un depósito cúbico de 2 m de arista. ¿Cuántos litros caben?","يُملأ خزان مكعب طول حرفه 2 م بالماء. كم لترًا يسع؟"),solution:r("$2^{3}=8\\ \\to\\ 8\\cdot 1000=8000$"),answer:{expected:o(8e3)}},{id:37,difficulty:"medium",question:a("Atzo 120 L/m² erori ziren. Zenbat milimetroko ur-geruza da?","Ayer cayeron 120 L/m². ¿A cuántos milímetros de altura de agua corresponden?","هطل أمس 120 لترًا لكل م². كم مليمترًا من ارتفاع الماء يوافق ذلك؟"),solution:a("1 L/m² = 1 mm, beraz 120 mm.","1 L/m² = 1 mm, así que 120 mm.","1 L/m² = 1 mm، إذن 120 مم."),answer:{expected:o(120)}},{id:38,difficulty:"hard",question:a("Prisma zeihar baten oinarriak 12 cm² ditu eta altuera 5 cm da. Zein da bolumena (cm³)? Zergatik?","Un prisma oblicuo tiene una base de 12 cm² y 5 cm de altura. ¿Cuál es su volumen (cm³)? ¿Por qué?","منشور مائل مساحة قاعدته 12 سم² وارتفاعه 5 سم. ما حجمه (سم³)؟ لماذا؟"),solution:a("Cavalieri: prisma zuzenaren bolumen bera, $12\\cdot 5=60$.","Cavalieri: el mismo volumen que el prisma recto, $12\\cdot 5=60$.","كافاليري: حجم المنشور القائم نفسه، $12\\cdot 5=60$."),answer:{expected:o(60)}},{id:39,difficulty:"hard",question:a("Ontzi ortoedriko baten oinarriak 20 cm × 15 cm neurtzen ditu. 9 L ur botatzen dira. Zer altueratara iristen da ura (cm)?","La base de un recipiente ortoédrico mide 20 cm × 15 cm. Se echan 9 L de agua. ¿Hasta qué altura llega el agua (cm)?","قاعدة إناء على شكل متوازي مستطيلات 20 سم × 15 سم. سُكب فيه 9 لترات من الماء. إلى أي ارتفاع يصل الماء (سم)؟"),solution:r("$9000\\mathbin{:}(20\\cdot 15)=30$"),answer:{expected:o(30)}},{id:40,difficulty:"hard",question:a("Zenbat m³ dira 1 km³?","¿Cuántos m³ son 1 km³?","كم م³ في 1 كم³؟"),solution:a("Hiru maila jaitsi: $1000\\cdot 1000\\cdot 1000=1\\,000\\,000\\,000$.","Se bajan tres escalones: $1000\\cdot 1000\\cdot 1000=1\\,000\\,000\\,000$.","ننزل ثلاث درجات: $1000\\cdot 1000\\cdot 1000=1\\,000\\,000\\,000$."),answer:{expected:o(1e9)}}]},{id:"volume",title:a("Gorputzen bolumena","Volumen de los cuerpos","حجوم الأجسام"),items:[{id:41,difficulty:"easy",question:l(a("Zilindro baten erradioa 10 cm da eta altuera 20 cm. Kalkulatu bolumena (cm³).","Un cilindro tiene 10 cm de radio y 20 cm de altura. Calcula su volumen (cm³).","أسطوانة نصف قطرها 10 سم وارتفاعها 20 سم. احسب حجمها (سم³)."),s),solution:r("$3{,}14\\cdot 10^{2}\\cdot 20=6280$"),answer:{expected:o(6280)}},{id:42,difficulty:"easy",question:a("Piramide baten oinarria 6 cm-ko aldeko karratua da eta altuera 5 cm. Kalkulatu bolumena (cm³).","La base de una pirámide es un cuadrado de 6 cm de lado y su altura mide 5 cm. Calcula su volumen (cm³).","قاعدة هرم مربع طول ضلعه 6 سم وارتفاعه 5 سم. احسب حجمه (سم³)."),solution:r("$\\frac{6^{2}\\cdot 5}{3}=60$"),answer:{expected:o(60)}},{id:43,difficulty:"easy",question:l(a("Kalkulatu 1 cm-ko erradioko bola baten bolumena (cm³).","Calcula el volumen de una bola de 1 cm de radio (cm³).","احسب حجم كرة نصف قطرها 1 سم (سم³)."),s,$),solution:r("$\\frac{4\\cdot 3{,}14\\cdot 1^{3}}{3}\\approx 4{,}19$"),answer:{expected:d("4,19")}},{id:44,difficulty:"medium",question:a("Prisma baten oinarria 5 cm eta 12 cm-ko katetoak dituen triangelu angeluzuzena da, eta altuera 20 cm. Kalkulatu bolumena (cm³).","La base de un prisma es un triángulo rectángulo de catetos 5 cm y 12 cm, y su altura mide 20 cm. Calcula su volumen (cm³).","قاعدة منشور مثلث قائم ضلعاه القائمان 5 سم و12 سم وارتفاعه 20 سم. احسب حجمه (سم³)."),solution:r("$\\frac{5\\cdot 12}{2}\\cdot 20=600$"),answer:{expected:o(600)}},{id:45,difficulty:"medium",question:l(a("Kono baten erradioa 9 cm da eta altuera 10 cm. Kalkulatu bolumena (cm³).","Un cono tiene 9 cm de radio y 10 cm de altura. Calcula su volumen (cm³).","مخروط نصف قطره 9 سم وارتفاعه 10 سم. احسب حجمه (سم³)."),s),solution:r("$\\frac{3{,}14\\cdot 9^{2}\\cdot 10}{3}=847{,}8$"),answer:{expected:d("847,8")}},{id:46,difficulty:"medium",question:a("Keopsen piramidearen oinarria 230 m-ko aldeko karratua da eta altuera 146 m. Kalkulatu bolumena (m³), unitateetara hurbilduta.","La pirámide de Keops tiene una base cuadrada de 230 m de lado y 146 m de altura. Calcula su volumen (m³), aproximado a las unidades.","قاعدة هرم خوفو مربع طول ضلعه 230 م وارتفاعه 146 م. احسب حجمه (م³) مقرّبًا إلى الآحاد."),solution:r("$\\frac{230^{2}\\cdot 146}{3}\\approx 2\\,574\\,467$"),answer:{expected:o(2574467)}},{id:47,difficulty:"medium",question:l(a("Ontzi batek 6 cm-ko erradioko erdiesfera forma du. Zenbat cm³ sartzen dira?","Un cuenco tiene forma de semiesfera de 6 cm de radio. ¿Cuántos cm³ caben?","وعاء على شكل نصف كرة نصف قطرها 6 سم. كم سم³ يسع؟"),s),solution:r("$\\frac{4\\cdot 3{,}14\\cdot 6^{3}}{3}\\mathbin{:}2=452{,}16$"),answer:{expected:d("452,16")}},{id:48,difficulty:"hard",question:a("10 cm-ko aldeko oinarri karratua eta 12 cm-ko altuera dituen piramide bat altueraren erdian mozten da. Kalkulatu enborraren bolumena (cm³).","Una pirámide de base cuadrada de 10 cm de lado y 12 cm de altura se corta a mitad de altura. Calcula el volumen del tronco (cm³).","هرم قاعدته مربع طول ضلعه 10 سم وارتفاعه 12 سم يُقطع عند منتصف ارتفاعه. احسب حجم الجذع (سم³)."),solution:r("$\\frac{10^{2}\\cdot 12}{3}-\\frac{5^{2}\\cdot 6}{3}=350$"),answer:{expected:o(350)}},{id:49,difficulty:"hard",question:l(a("Izozki bat 3 cm-ko erradioko eta 10 cm-ko altuerako konoa da, gainean erradio bereko erdiesfera bat duela. Zein da bolumena (cm³)?","Un helado es un cono de 3 cm de radio y 10 cm de altura con una semiesfera del mismo radio encima. ¿Cuál es su volumen (cm³)?","مثلجات على شكل مخروط نصف قطره 3 سم وارتفاعه 10 سم فوقه نصف كرة بنصف القطر نفسه. ما حجمها (سم³)؟"),s),solution:r("$\\frac{3{,}14\\cdot 3^{2}\\cdot 10}{3}+\\frac{2\\cdot 3{,}14\\cdot 3^{3}}{3}=150{,}72$"),answer:{expected:d("150,72")}},{id:50,difficulty:"hard",question:a("3 cm-ko erradioko eta 4 cm-ko altuerako zilindro bat urtu eta 3 cm-ko erradioko bolak egiten dira. Zenbat bola ateratzen dira?","Se funde un cilindro de 3 cm de radio y 4 cm de altura y se hacen bolas de 3 cm de radio. ¿Cuántas bolas salen?","تُصهر أسطوانة نصف قطرها 3 سم وارتفاعها 4 سم وتُصنع منها كرات نصف قطرها 3 سم. كم كرة نحصل عليها؟"),solution:a("Bolumen bera dute: $3{,}14\\cdot 3^{2}\\cdot 4=113{,}04$ eta $\\frac{4\\cdot 3{,}14\\cdot 3^{3}}{3}=113{,}04$. Bola 1.","Tienen el mismo volumen: $3{,}14\\cdot 3^{2}\\cdot 4=113{,}04$ y $\\frac{4\\cdot 3{,}14\\cdot 3^{3}}{3}=113{,}04$. Sale 1 bola.","لهما الحجم نفسه: $3{,}14\\cdot 3^{2}\\cdot 4=113{,}04$ و$\\frac{4\\cdot 3{,}14\\cdot 3^{3}}{3}=113{,}04$. كرة واحدة."),answer:{expected:o(1)}}]}];function k({game:t}){return t==="race"?n.jsxs("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:[n.jsx("rect",{x:"6",y:"36",width:"208",height:"52",rx:"10",fill:"var(--paper-deep)",stroke:"var(--ink)",strokeWidth:"2"}),n.jsx("line",{x1:"14",y1:"62",x2:"206",y2:"62",stroke:"var(--line)",strokeWidth:"2",strokeDasharray:"8 7"}),n.jsx(g,{color:"var(--coral)",label:"V",x:104,y:20,width:72}),n.jsx(g,{color:"var(--blue)",x:40,y:50,width:62}),n.jsx("text",{x:"110",y:"112",textAnchor:"middle",fontSize:"16",fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:"V = A · h"})]}):n.jsx("svg",{className:"fraction-v2-game-art",viewBox:"0 0 220 120","aria-hidden":"true",children:["1 m³","1000 L","6 · 4²","96"].map((u,c)=>n.jsxs("g",{transform:`translate(${14+c*50} ${c%2===0?24:40}) rotate(${c%2===0?-4:4})`,children:[n.jsx("rect",{width:"44",height:"60",rx:"8",fill:c%2===0?"var(--paper-deep)":"var(--blue-tint, #dde7f7)",stroke:"var(--ink)",strokeWidth:"2"}),n.jsx("text",{x:"22",y:"36",textAnchor:"middle",fontSize:u.length>4?10:12,fontWeight:"700",fill:"var(--ink)",direction:"ltr",children:u})]},u))})}const h="matella-gorputzak-dbh2-game-records",p=[{id:"race",title:{eu:"Gorputzen lasterketa",es:"Carrera de cuerpos",ar:"سباق الأجسام"},tagline:{eu:"Erantzun ondo eta azkar: zure autoa aurrera doa, akatsek irrist egiten dute.",es:"Responde bien y rápido: tu coche avanza, los errores le hacen derrapar.",ar:"أجب بدقة وسرعة: تتقدم سيارتك، والأخطاء تجعلها تنزلق."},skills:{eu:"Bost zirkuitu, etapa bakoitzeko bat",es:"Cinco circuitos, uno por etapa",ar:"خمس حلبات، واحدة لكل مرحلة"},levels:[{progressId:34101,stage:"polyhedra",title:{eu:"Poliedroak",es:"Poliedros",ar:"متعددات الأوجه"},description:{eu:"Aurpegiak, ertzak, erpinak eta Euler.",es:"Caras, aristas, vértices y Euler.",ar:"الأوجه والأحرف والرؤوس وأويلر."}},{progressId:34102,stage:"areas",title:{eu:"Azalerak",es:"Áreas",ar:"المساحات"},description:{eu:"Kuboak, ortoedroak eta piramideak.",es:"Cubos, ortoedros y pirámides.",ar:"المكعبات ومتوازيات المستطيلات والأهرامات."}},{progressId:34103,stage:"round",title:{eu:"Biraketa-gorputzak",es:"Cuerpos de revolución",ar:"الأجسام الدورانية"},description:{eu:"Zilindroa, konoa eta esfera.",es:"Cilindro, cono y esfera.",ar:"الأسطوانة والمخروط والكرة."}},{progressId:34104,stage:"units",title:{eu:"Unitateak eta litroak",es:"Unidades y litros",ar:"الوحدات واللترات"},description:{eu:"m³, dm³, cm³ eta L.",es:"m³, dm³, cm³ y L.",ar:"m³ وdm³ وcm³ وL."}},{progressId:34105,stage:"volume",title:{eu:"Bolumenak",es:"Volúmenes",ar:"الحجوم"},description:{eu:"Prismak, piramideak, zilindroak, konoak eta esferak.",es:"Prismas, pirámides, cilindros, conos y esferas.",ar:"المناشير والأهرامات والأسطوانات والمخاريط والكرات."}}]},{id:"memory",title:{eu:"Memoria",es:"Memoria",ar:"الذاكرة"},tagline:{eu:"Aurkitu balio bera duten kartak.",es:"Encuentra las cartas que valen lo mismo.",ar:"جد البطاقات ذات القيمة نفسها."},skills:{eu:"Unitateak, azalerak eta bolumenak",es:"Unidades, áreas y volúmenes",ar:"الوحدات والمساحات والحجوم"},levels:[{progressId:34201,stage:"units",title:{eu:"Unitateak",es:"Unidades",ar:"الوحدات"},description:{eu:"2,5 m³ ↔ 2500 dm³",es:"2,5 m³ ↔ 2500 dm³",ar:"2.5 m³ ↔ 2500 dm³"}},{progressId:34202,stage:"areas",title:{eu:"Azalerak",es:"Áreas",ar:"المساحات"},description:{eu:"6 · 4² ↔ 96",es:"6 · 4² ↔ 96",ar:"6 · 4² ↔ 96"}},{progressId:34203,stage:"volume",title:{eu:"Bolumenak",es:"Volúmenes",ar:"الحجوم"},description:{eu:"6² · 9 : 3 ↔ 108",es:"6² · 9 : 3 ↔ 108",ar:"6² · 9 : 3 ↔ 108"}}]}],ca=L(p),ma={race:"lasterketa",memory:"memoria"};function pa(t){const u=t.match(/\/(?:juegos|jokuak)\/([a-z-]+)$/)?.[1];return u?["carrera","lasterketa"].includes(u)?"race":["memoria","memory"].includes(u)?"memory":"hub":"hub"}const $a={game:p.find(t=>t.id==="race"),generate:_,checkPit:j,parTime:E,errorTip:t=>C[t??"calculation"],pitPlaceholder:()=>"188,4",pitUnreadable:{eu:"Idatzi zenbaki bat, adibidez 96 edo 188,4.",es:"Escribe un número, por ejemplo 96 o 188,4.",ar:"اكتب عددًا، مثل 96 أو 188.4."},pitWrongForm:{eu:"Idatzi zenbaki gisa.",es:"Escríbelo como número.",ar:"اكتبه عددًا."}};function ka(t){return n.jsx(q,{...t,rules:$a,art:n.jsx(k,{game:"race"})})}const ba=p.find(t=>t.id==="memory"),ga={race:ka,memory:t=>n.jsx(na,{...t,config:{game:ba,art:n.jsx(k,{game:"memory"}),pairs:K,createBoard:Z}})},za=p.map(t=>({info:t,art:n.jsx(k,{game:t.id}),component:ga[t.id]}));function ha({language:t,pathname:u,openGame:c,completedIds:y,onComplete:f}){return n.jsx(v,{language:t,games:za,recordsKey:h,title:{eu:"Jolastu eta hobetu zure marka",es:"Juega y mejora tu marca",ar:"العب وحسّن رقمك"},completedIds:y,onComplete:f,mode:pa(u),onModeChange:b=>c(b==="hub"?null:ma[b])})}const x=[{id:"polyhedra",tone:"blue",title:{eu:"Poliedroak",es:"Poliedros",ar:"متعددات الأوجه"}},{id:"areas",tone:"violet",title:{eu:"Poliedroen azalerak",es:"Áreas de poliedros",ar:"مساحات متعددات الأوجه"}},{id:"round",tone:"mustard",title:{eu:"Biraketa-gorputzak",es:"Cuerpos de revolución",ar:"الأجسام الدورانية"}},{id:"units",tone:"coral",title:{eu:"Bolumena eta edukiera",es:"Volumen y capacidad",ar:"الحجم والسعة"}},{id:"volume",tone:"green",title:{eu:"Gorputzen bolumena",es:"Volumen de los cuerpos",ar:"حجوم الأجسام"}}],e=(t,u,c)=>({eu:t,es:u,ar:c.replace(/\{,\}/g,".")}),i=t=>({eu:t,es:t,ar:t.replace(/\{,\}/g,".")}),xa=[{id:"elements",stage:"polyhedra",title:e("Poliedroen elementuak","Elementos de los poliedros","عناصر متعددات الأوجه"),goal:e("Poliedro baten aurpegiak, ertzak eta erpinak ezagutzea eta prismak eta piramideak bereiztea.","Reconocer las caras, aristas y vértices de un poliedro y distinguir prismas y pirámides.","التعرّف إلى أوجه متعدد الأوجه وأحرفه ورؤوسه والتمييز بين المناشير والأهرامات."),explanation:e("Poliedroa poligonoz mugatutako gorputza da. Poligono horiek aurpegiak dira; bi aurpegi elkartzen diren lerroak, ertzak; eta hainbat ertz elkartzen diren puntuak, erpinak. Prismak bi oinarri berdin eta paralelo ditu, eta alboko aurpegiak paralelogramoak dira; oinarriko poligonoak ematen dio izena: prisma triangeluarra, pentagonala… Piramideak oinarri bakarra du, eta alboko aurpegiak erpin batean elkartzen diren triangeluak dira. Oinarriak $n$ alde baditu, prismak $n+2$ aurpegi, $3n$ ertz eta $2n$ erpin ditu; piramideak $n+1$ aurpegi, $2n$ ertz eta $n+1$ erpin. Oinarriak poligono erregularrak eta alboko aurpegiak berdinak badira, prisma edo piramide erregularra da.","Un poliedro es un cuerpo limitado por polígonos. Esos polígonos son las caras; las líneas donde se juntan dos caras, las aristas; y los puntos donde se juntan varias aristas, los vértices. Un prisma tiene dos bases iguales y paralelas, y sus caras laterales son paralelogramos; el polígono de la base le da nombre: prisma triangular, pentagonal… Una pirámide tiene una sola base, y sus caras laterales son triángulos que se juntan en un vértice. Si la base tiene $n$ lados, el prisma tiene $n+2$ caras, $3n$ aristas y $2n$ vértices; la pirámide, $n+1$ caras, $2n$ aristas y $n+1$ vértices. Si las bases son polígonos regulares y las caras laterales iguales, el prisma o la pirámide es regular.","متعدد الأوجه جسم تحدّه مضلعات. هذه المضلعات هي الأوجه؛ والخطوط التي يلتقي عندها وجهان هي الأحرف؛ والنقاط التي تلتقي عندها عدة أحرف هي الرؤوس. للمنشور قاعدتان متطابقتان ومتوازيتان، وأوجهه الجانبية متوازيات أضلاع؛ ويأخذ اسمه من مضلع القاعدة: منشور ثلاثي، خماسي… وللهرم قاعدة واحدة، وأوجهه الجانبية مثلثات تلتقي في رأس واحد. إذا كان للقاعدة $n$ أضلاع فللمنشور $n+2$ وجهًا و$3n$ حرفًا و$2n$ رأسًا؛ وللهرم $n+1$ وجهًا و$2n$ حرفًا و$n+1$ رأسًا. وإذا كانت القاعدتان مضلعين منتظمين والأوجه الجانبية متطابقة كان المنشور أو الهرم منتظمًا."),problem:e("Zenbat aurpegi, ertz eta erpin ditu prisma hexagonal batek? Eta piramide hexagonal batek?","¿Cuántas caras, aristas y vértices tiene un prisma hexagonal? ¿Y una pirámide hexagonal?","كم وجهًا وحرفًا ورأسًا للمنشور السداسي؟ وللهرم السداسي؟"),stepsKind:"steps",steps:[{text:e("Hexagonoa: $n=6$ alde.","Hexágono: $n=6$ lados.","المسدس: $n=6$ أضلاع.")},{text:e("Prisma: 6 alboko aurpegi eta 2 oinarri; ertzak 6 + 6 + 6; erpinak 6 + 6.","Prisma: 6 caras laterales y 2 bases; aristas 6 + 6 + 6; vértices 6 + 6.","المنشور: 6 أوجه جانبية وقاعدتان؛ الأحرف 6 + 6 + 6؛ الرؤوس 6 + 6."),math:i("$8,\\ 18,\\ 12$")},{text:e("Piramidea: 6 triangelu eta oinarria; 6 oinarrian eta 6 erpinera; 6 + 1 erpin.","Pirámide: 6 triángulos y la base; 6 aristas en la base y 6 hacia el vértice; 6 + 1 vértices.","الهرم: 6 مثلثات والقاعدة؛ 6 أحرف في القاعدة و6 نحو الرأس؛ 6 + 1 رؤوس."),math:i("$7,\\ 12,\\ 7$")}],example:i("$n=5\\ \\to\\ 7,\\ 15,\\ 10\\qquad 6,\\ 10,\\ 6$"),takeaway:e("Aurpegiak poligonoak dira, ertzak lerroak eta erpinak puntuak. Prismak bi oinarri, piramideak bat.","Las caras son polígonos, las aristas líneas y los vértices puntos. El prisma tiene dos bases; la pirámide, una.","الأوجه مضلعات، والأحرف خطوط، والرؤوس نقاط. للمنشور قاعدتان وللهرم قاعدة واحدة."),figure:t=>n.jsx(U,{language:t})},{id:"euler",stage:"polyhedra",title:e("Eulerren formula","La fórmula de Euler","صيغة أويلر"),goal:e("Poliedro ganbiletan aurpegien, erpinen eta ertzen arteko erlazioa egiaztatzea eta erabiltzea.","Comprobar y usar la relación entre caras, vértices y aristas de los poliedros convexos.","التحقق من العلاقة بين الأوجه والرؤوس والأحرف في متعددات الأوجه المحدّبة واستعمالها."),explanation:e("Poliedro bat ganbila da edozein aurpegiren planoak poliedro osoa alde batean uzten badu; bestela, ahurra da (zulo edo koska bat du). Poliedro ganbil guztietan Leonhard Eulerrek aurkitutako erlazio hau betetzen da: aurpegiak + erpinak = ertzak + 2. Kuboan: $6+8=12+2$. Formulari esker, bi datu jakinda hirugarrena kalkula daiteke: 12 erpin eta 30 ertz baditu, aurpegiak $30+2-12=20$ dira. Erlazioa betetzen ez bada, gorputz hori ezin da poliedro ganbila izan; egiaztapen ona da zenbaketak berrikusteko.","Un poliedro es convexo si el plano de cualquier cara deja todo el poliedro a un mismo lado; si no, es cóncavo (tiene un hueco o entrante). En todos los poliedros convexos se cumple esta relación, descubierta por Leonhard Euler: caras + vértices = aristas + 2. En el cubo: $6+8=12+2$. Gracias a la fórmula, conociendo dos datos se calcula el tercero: si tiene 12 vértices y 30 aristas, las caras son $30+2-12=20$. Si la relación no se cumple, ese cuerpo no puede ser un poliedro convexo; es una buena comprobación para revisar los recuentos.","يكون متعدد الأوجه محدّبًا إذا ترك مستوى أي وجه الجسمَ كله في جهة واحدة؛ وإلا فهو مقعّر (فيه تجويف أو انبعاج). وفي جميع متعددات الأوجه المحدّبة تتحقق هذه العلاقة التي اكتشفها ليونهارد أويلر: الأوجه + الرؤوس = الأحرف + 2. في المكعب: $6+8=12+2$. وبفضل الصيغة نحسب المعطى الثالث إذا عرفنا اثنين: إذا كان له 12 رأسًا و30 حرفًا فعدد أوجهه $30+2-12=20$. وإذا لم تتحقق العلاقة فلا يمكن أن يكون الجسم متعدد أوجه محدّبًا؛ إنها طريقة جيدة لمراجعة العدّ."),problem:e("Poliedro ganbil batek 9 aurpegi eta 16 ertz ditu. Zenbat erpin ditu?","Un poliedro convexo tiene 9 caras y 16 aristas. ¿Cuántos vértices tiene?","متعدد أوجه محدّب له 9 أوجه و16 حرفًا. كم رأسًا له؟"),stepsKind:"steps",steps:[{text:e("Idatzi formula datuekin.","Escribe la fórmula con los datos.","اكتب الصيغة بالمعطيات."),math:e("$9+E=16+2$","$9+V=16+2$","$9+V=16+2$")},{text:e("Askatu erpinak.","Despeja los vértices.","استخرج عدد الرؤوس."),math:i("$18-9=9$")},{text:e("Egiaztatu: adibidez, piramide oktogonal bat (9, 16, 9).","Comprueba: por ejemplo, una pirámide octogonal (9, 16, 9).","تحقّق: مثلًا هرم ثماني (9، 16، 9).")}],example:i("$6+8=12+2\\qquad 20+12=30+2$"),takeaway:e("Poliedro ganbiletan: aurpegiak + erpinak = ertzak + 2.","En los poliedros convexos: caras + vértices = aristas + 2.","في متعددات الأوجه المحدّبة: الأوجه + الرؤوس = الأحرف + 2."),figure:t=>n.jsx(w,{language:t})},{id:"regular",stage:"polyhedra",title:e("Poliedro erregularrak","Poliedros regulares","متعددات الأوجه المنتظمة"),goal:e("Bost poliedro erregularrak ezagutzea eta zergatik ez dagoen besterik azaltzea.","Conocer los cinco poliedros regulares y explicar por qué no hay más.","معرفة متعددات الأوجه المنتظمة الخمسة وتفسير عدم وجود غيرها."),explanation:e("Poliedro erregular batean aurpegi guztiak poligono erregular berdinak dira, eta erpin guztietan aurpegi kopuru bera elkartzen da. Bost besterik ez daude: tetraedroa (4 triangelu), kuboa (6 karratu), oktaedroa (8 triangelu), dodekaedroa (12 pentagono) eta ikosaedroa (20 triangelu). Zergatik bost? Erpin batean gutxienez hiru aurpegi elkartu behar dira, eta haien angeluen baturak 360° baino txikiagoa izan behar du; 360° izanez gero, laua geratzen da. Triangeluekin 3, 4 edo 5 ($180°$, $240°$, $300°$); karratuekin 3 ($270°$); pentagonoekin 3 ($324°$). Sei triangelu edo hiru hexagono 360° dira, eta ez dago gehiago.","En un poliedro regular todas las caras son polígonos regulares iguales y en todos los vértices se junta el mismo número de caras. Solo hay cinco: tetraedro (4 triángulos), cubo (6 cuadrados), octaedro (8 triángulos), dodecaedro (12 pentágonos) e icosaedro (20 triángulos). ¿Por qué cinco? En un vértice se tienen que juntar al menos tres caras, y la suma de sus ángulos tiene que ser menor que 360°; si es 360°, queda plano. Con triángulos, 3, 4 o 5 ($180°$, $240°$, $300°$); con cuadrados, 3 ($270°$); con pentágonos, 3 ($324°$). Seis triángulos o tres hexágonos suman 360°, y no hay más.","في متعدد الأوجه المنتظم جميع الأوجه مضلعات منتظمة متطابقة، ويلتقي العدد نفسه من الأوجه عند كل رأس. وهي خمسة فقط: رباعي الأوجه (4 مثلثات)، والمكعب (6 مربعات)، وثماني الأوجه (8 مثلثات)، واثنا عشري الأوجه (12 مخمسًا)، وعشريني الأوجه (20 مثلثًا). لماذا خمسة؟ يجب أن يلتقي عند الرأس ثلاثة أوجه على الأقل، ويجب أن يكون مجموع زواياها أقل من 360°؛ فإن كان 360° بقي مستويًا. بالمثلثات 3 أو 4 أو 5 ($180°$، $240°$، $300°$)؛ وبالمربعات 3 ($270°$)؛ وبالمخمسات 3 ($324°$). ستة مثلثات أو ثلاثة مسدسات مجموعها 360°، ولا يوجد غيرها."),problem:e("Zenbat ertz ditu ikosaedroak? (20 triangelu; erpin bakoitzean 5 aurpegi)","¿Cuántas aristas tiene el icosaedro? (20 triángulos; 5 caras en cada vértice)","كم حرفًا لعشريني الأوجه؟ (20 مثلثًا؛ 5 أوجه عند كل رأس)"),stepsKind:"steps",steps:[{text:e("Zenbatu triangeluen alde guztiak.","Cuenta todos los lados de los triángulos.","عُدّ جميع أضلاع المثلثات."),math:i("$20\\cdot 3=60$")},{text:e("Ertz bakoitza bi aurpegik partekatzen dute: zatitu 2z.","Cada arista la comparten dos caras: divide entre 2.","كل حرف مشترك بين وجهين: اقسم على 2."),math:i("$60\\mathbin{:}2=30$")},{text:e("Erpinak: 60 erpin, 5 aurpegitan banatuta.","Vértices: 60 esquinas repartidas de 5 en 5.","الرؤوس: 60 زاوية موزعة خمسًا خمسًا."),math:i("$60\\mathbin{:}5=12$")}],example:i("$4+4=6+2\\qquad 12+20=30+2$"),takeaway:e("Bost poliedro erregular: tetraedroa, kuboa, oktaedroa, dodekaedroa eta ikosaedroa.","Cinco poliedros regulares: tetraedro, cubo, octaedro, dodecaedro e icosaedro.","خمسة متعددات أوجه منتظمة: رباعي الأوجه، والمكعب، وثماني الأوجه، واثنا عشري الأوجه، وعشريني الأوجه."),figure:t=>n.jsx(B,{language:t})},{id:"prism-area",stage:"areas",title:e("Prismaren azalera","Área del prisma","مساحة المنشور"),goal:e("Prisma baten garapena marraztea eta alboko azalera eta azalera osoa kalkulatzea.","Dibujar el desarrollo de un prisma y calcular su área lateral y total.","رسم نشر المنشور وحساب مساحته الجانبية والكلية."),explanation:e("Prisma bat ireki eta mahai gainean zabaltzen badugu, haren garapen laua lortzen dugu: alboko aurpegiek laukizuzen bat osatzen dute, eta bi oinarriak alde banatan geratzen dira. Laukizuzen horren oinarria oinarriaren perimetroa da, eta altuera prismaren altuera. Beraz, alboko azalera $A_L=P\\cdot h$ da, eta azalera osoa $A_T=A_L+2\\cdot A_O$. Ortoedroan sei laukizuzen daude, binaka berdinak: $A_T=2(ab+ac+bc)$. Kuboan sei karratu: $A_T=6l^{2}$. Oinarria poligono erregularra bada, haren azalera perimetroa bider apotema zati bi da.","Si abrimos un prisma y lo extendemos sobre la mesa, obtenemos su desarrollo plano: las caras laterales forman un rectángulo y las dos bases quedan a cada lado. La base de ese rectángulo es el perímetro de la base y su altura, la altura del prisma. Por eso el área lateral es $A_L=P\\cdot h$ y el área total, $A_T=A_L+2\\cdot A_B$. En el ortoedro hay seis rectángulos, iguales dos a dos: $A_T=2(ab+ac+bc)$. En el cubo, seis cuadrados: $A_T=6l^{2}$. Si la base es un polígono regular, su área es el perímetro por la apotema entre dos.","إذا فتحنا المنشور وبسطناه على الطاولة حصلنا على نشره المستوي: تكوّن الأوجه الجانبية مستطيلًا، وتبقى القاعدتان على جانبيه. قاعدة هذا المستطيل محيط القاعدة وارتفاعه ارتفاع المنشور. لذلك المساحة الجانبية $A_L=P\\cdot h$ والمساحة الكلية $A_T=A_L+2\\cdot A_B$. في متوازي المستطيلات ستة مستطيلات متطابقة مثنى مثنى: $A_T=2(ab+ac+bc)$. وفي المكعب ستة مربعات: $A_T=6l^{2}$. وإذا كانت القاعدة مضلعًا منتظمًا فمساحتها المحيط في العامد مقسومًا على اثنين."),problem:e("Ortoedro baten neurriak 4 cm, 3 cm eta 12 cm dira. Kalkulatu azalera osoa.","Las dimensiones de un ortoedro son 4 cm, 3 cm y 12 cm. Calcula su área total.","أبعاد متوازي مستطيلات 4 سم و3 سم و12 سم. احسب مساحته الكلية."),stepsKind:"steps",steps:[{text:e("Hiru laukizuzen desberdinak.","Los tres rectángulos distintos.","المستطيلات الثلاثة المختلفة."),math:i("$4\\cdot 3=12\\quad 4\\cdot 12=48\\quad 3\\cdot 12=36$")},{text:e("Bakoitza bi aldiz dago.","Cada uno está dos veces.","كل منها مرتان."),math:i("$2\\cdot (12+48+36)=192$")},{text:e("Azalera osoa: 192 cm².","Área total: 192 cm².","المساحة الكلية: 192 سم².")}],example:e("$A_L=P\\cdot h\\qquad A_T=A_L+2A_O$","$A_L=P\\cdot h\\qquad A_T=A_L+2A_B$","$A_L=P\\cdot h\\qquad A_T=A_L+2A_B$"),takeaway:e("Alboko azalera: perimetroa bider altuera. Gero gehitu bi oinarriak.","Área lateral: perímetro por altura. Luego suma las dos bases.","المساحة الجانبية: المحيط في الارتفاع. ثم أضف القاعدتين."),figure:t=>n.jsx(S,{language:t})},{id:"pyramid-area",stage:"areas",title:e("Piramidearen azalera","Área de la pirámide","مساحة الهرم"),goal:e("Piramide erregular baten azalera kalkulatzea, apotema Pitagorasekin aurkituz behar denean.","Calcular el área de una pirámide regular, hallando la apotema con Pitágoras cuando haga falta.","حساب مساحة هرم منتظم، مع إيجاد العامد بفيثاغورس عند الحاجة."),explanation:e("Piramide erregular baten garapena oinarria eta haren inguruko triangelu isoszele berdinak dira. Triangelu horien altuera piramidearen apotema da ($a$); ez da piramidearen altuera ($h$), ez eta oinarriaren apotema ($a'$) ere. Alboko azalera triangeluen azaleren batura da: $A_L=\\frac{P\\cdot a}{2}$, eta azalera osoa $A_T=A_L+A_O$. Apotema ematen ez badute, triangelu angeluzuzen bat bilatu: altuera eta oinarriaren apotema katetoak dira, eta piramidearen apotema hipotenusa: $a=\\sqrt{h^{2}+a'^{2}}$. Oinarri karratuan, $a'$ aldearen erdia da.","El desarrollo de una pirámide regular es la base y, alrededor, triángulos isósceles iguales. La altura de esos triángulos es la apotema de la pirámide ($a$); no es la altura de la pirámide ($h$) ni la apotema de la base ($a'$). El área lateral es la suma de las áreas de los triángulos: $A_L=\\frac{P\\cdot a}{2}$, y el área total, $A_T=A_L+A_B$. Si no dan la apotema, busca un triángulo rectángulo: la altura y la apotema de la base son los catetos, y la apotema de la pirámide la hipotenusa: $a=\\sqrt{h^{2}+a'^{2}}$. En una base cuadrada, $a'$ es la mitad del lado.","نشر الهرم المنتظم هو القاعدة وحولها مثلثات متساوية الساقين متطابقة. ارتفاع هذه المثلثات هو عامد الهرم ($a$)؛ وليس ارتفاع الهرم ($h$) ولا عامد القاعدة ($a'$). المساحة الجانبية مجموع مساحات المثلثات: $A_L=\\frac{P\\cdot a}{2}$، والمساحة الكلية $A_T=A_L+A_B$. وإذا لم يُعطَ العامد فابحث عن مثلث قائم: الارتفاع وعامد القاعدة ضلعاه القائمان، وعامد الهرم وتره: $a=\\sqrt{h^{2}+a'^{2}}$. وفي القاعدة المربعة $a'$ نصف الضلع."),problem:e("Piramide erregular baten oinarria 6 dm-ko aldeko karratua da, eta altuera 4 dm. Kalkulatu azalera osoa.","La base de una pirámide regular es un cuadrado de 6 dm de lado y su altura mide 4 dm. Calcula su área total.","قاعدة هرم منتظم مربع طول ضلعه 6 دسم وارتفاعه 4 دسم. احسب مساحته الكلية."),stepsKind:"steps",steps:[{text:e("Apotema: altuera eta aldearen erdia katetoak dira.","Apotema: la altura y medio lado son los catetos.","العامد: الارتفاع ونصف الضلع هما الضلعان القائمان."),math:i("$a=\\sqrt{4^{2}+3^{2}}=5$")},{text:e("Lau triangelu.","Cuatro triángulos.","أربعة مثلثات."),math:i("$4\\cdot \\frac{6\\cdot 5}{2}=60$")},{text:e("Gehitu oinarria.","Suma la base.","أضف القاعدة."),math:i("$60+36=96$")}],example:e("$A_L=\\frac{P\\cdot a}{2}\\qquad a=\\sqrt{h^{2}+a'^{2}}$","$A_L=\\frac{P\\cdot a}{2}\\qquad a=\\sqrt{h^{2}+a'^{2}}$","$A_L=\\frac{P\\cdot a}{2}\\qquad a=\\sqrt{h^{2}+a'^{2}}$"),takeaway:e("Alboko azalera: perimetroa bider piramidearen apotema, zati bi. Apotema ≠ altuera.","Área lateral: perímetro por apotema de la pirámide entre dos. Apotema ≠ altura.","المساحة الجانبية: المحيط في عامد الهرم على اثنين. العامد ≠ الارتفاع."),figure:t=>n.jsx(V,{language:t})},{id:"frustum-area",stage:"areas",title:e("Piramide-enborraren azalera","Área del tronco de pirámide","مساحة جذع الهرم"),goal:e("Piramide-enbor baten azalera kalkulatzea alboko trapezioak eta bi oinarriak batuz.","Calcular el área de un tronco de pirámide sumando los trapecios laterales y las dos bases.","حساب مساحة جذع الهرم بجمع أشباه المنحرفات الجانبية والقاعدتين."),explanation:e("Piramide bat oinarriarekiko paralelo den plano batez mozten badugu, behealdean piramide-enborra geratzen da. Bi oinarri ditu, paraleloak baina desberdinak, eta alboko aurpegiak trapezioak dira. Trapezio horien altuera enborraren apotema da. Alboko azalera trapezioen batura da: enbor erregularrean, $A_L=\\frac{(P+P')\\cdot a}{2}$, bi perimetroak erabiliz. Azalera osoa lortzeko, gehitu bi oinarriak. Apotema ematen ez badute, trapezioan triangelu angeluzuzen bat dago: alboko ertza hipotenusa da, eta katetoetako bat oinarrien aldeen kenduraren erdia.","Si cortamos una pirámide por un plano paralelo a la base, abajo queda un tronco de pirámide. Tiene dos bases, paralelas pero distintas, y sus caras laterales son trapecios. La altura de esos trapecios es la apotema del tronco. El área lateral es la suma de los trapecios: en un tronco regular, $A_L=\\frac{(P+P')\\cdot a}{2}$, con los dos perímetros. Para el área total, suma las dos bases. Si no dan la apotema, en el trapecio hay un triángulo rectángulo: la arista lateral es la hipotenusa, y uno de los catetos es la mitad de la diferencia de los lados de las bases.","إذا قطعنا الهرم بمستوى موازٍ للقاعدة بقي في الأسفل جذع هرم. له قاعدتان متوازيتان لكنهما مختلفتان، وأوجهه الجانبية أشباه منحرفات. ارتفاع هذه الأشكال هو عامد الجذع. المساحة الجانبية مجموع أشباه المنحرفات: في الجذع المنتظم $A_L=\\frac{(P+P')\\cdot a}{2}$ باستعمال المحيطين. وللمساحة الكلية أضف القاعدتين. وإذا لم يُعطَ العامد ففي شبه المنحرف مثلث قائم: الحرف الجانبي وتره، وأحد ضلعيه القائمين نصف الفرق بين ضلعي القاعدتين."),problem:e("Piramide-enbor erregular baten oinarriak 20 cm eta 10 cm-ko aldeko karratuak dira, eta alboko ertzak 13 cm. Kalkulatu azalera osoa.","Las bases de un tronco de pirámide regular son cuadrados de 20 cm y 10 cm de lado, y las aristas laterales miden 13 cm. Calcula su área total.","قاعدتا جذع هرم منتظم مربعان طولا ضلعيهما 20 سم و10 سم، وأحرفه الجانبية 13 سم. احسب مساحته الكلية."),stepsKind:"steps",steps:[{text:e("Trapezioaren altuera: katetoa $(20-10)\\mathbin{:}2=5$.","Altura del trapecio: cateto $(20-10)\\mathbin{:}2=5$.","ارتفاع شبه المنحرف: الضلع القائم $(20-10)\\mathbin{:}2=5$."),math:i("$\\sqrt{13^{2}-5^{2}}=12$")},{text:e("Lau trapezio.","Cuatro trapecios.","أربعة أشباه منحرفات."),math:i("$4\\cdot \\frac{(20+10)\\cdot 12}{2}=720$")},{text:e("Gehitu bi oinarriak.","Suma las dos bases.","أضف القاعدتين."),math:i("$720+400+100=1220$")}],example:i("$A_L=\\frac{(P+P')\\cdot a}{2}$"),takeaway:e("Enborra: trapezioak gehi bi oinarri. Apotema trapezioaren altuera da.","Tronco: trapecios más dos bases. La apotema es la altura del trapecio.","الجذع: أشباه منحرفات مع قاعدتين. العامد ارتفاع شبه المنحرف."),figure:t=>n.jsx(T,{language:t})},{id:"cylinder",stage:"round",title:e("Zilindroa","El cilindro","الأسطوانة"),goal:e("Zilindroa biraketa-gorputz gisa ulertzea eta haren azalera garapenetik kalkulatzea.","Entender el cilindro como cuerpo de revolución y calcular su área a partir del desarrollo.","فهم الأسطوانة جسمًا دورانيًا وحساب مساحتها من نشرها."),explanation:e("Biraketa-gorputzak irudi lau bat ardatz baten inguruan biratuz sortzen dira. Laukizuzen bat bere alde baten inguruan biratzen bada, zilindroa sortzen da: ardatza zilindroaren altuera da, eta beste aldeak oinarrien erradioa ematen du. Zilindroaren garapena laukizuzen bat eta bi zirkulu dira. Laukizuzenaren oinarria zirkunferentziaren luzera da, $2\\pi r$, eta altuera zilindroarena. Beraz, $A_L=2\\pi r\\cdot h$ eta $A_T=2\\pi r h+2\\pi r^{2}$. Kalkuluetan $\\pi\\approx 3{,}14$ erabiliko dugu. Kontuz: diametroa ematen badute, erdia hartu erradioa lortzeko.","Los cuerpos de revolución se generan al girar una figura plana alrededor de un eje. Si un rectángulo gira alrededor de uno de sus lados, se genera un cilindro: el eje es la altura del cilindro y el otro lado da el radio de las bases. El desarrollo del cilindro es un rectángulo y dos círculos. La base del rectángulo es la longitud de la circunferencia, $2\\pi r$, y su altura la del cilindro. Por eso $A_L=2\\pi r\\cdot h$ y $A_T=2\\pi r h+2\\pi r^{2}$. En las cuentas usaremos $\\pi\\approx 3{,}14$. Cuidado: si dan el diámetro, toma la mitad para el radio.","تنشأ الأجسام الدورانية بدوران شكل مستوٍ حول محور. إذا دار مستطيل حول أحد أضلاعه نشأت أسطوانة: المحور ارتفاع الأسطوانة، والضلع الآخر يعطي نصف قطر القاعدتين. نشر الأسطوانة مستطيل ودائرتان. قاعدة المستطيل طول محيط الدائرة $2\\pi r$، وارتفاعه ارتفاع الأسطوانة. لذلك $A_L=2\\pi r\\cdot h$ و$A_T=2\\pi r h+2\\pi r^{2}$. سنستعمل في الحسابات $\\pi\\approx 3{,}14$. انتبه: إذا أُعطي القطر فخذ نصفه لنصف القطر."),problem:e("Ur-biltegi zilindriko itxi batek 0,5 m-ko erradioa eta 2 m-ko altuera ditu. Zenbat txapa behar da?","Un depósito cilíndrico cerrado tiene 0,5 m de radio y 2 m de altura. ¿Cuánta chapa hace falta?","خزان أسطواني مغلق نصف قطره 0.5 م وارتفاعه 2 م. كم يلزم من الصفيح؟"),stepsKind:"steps",steps:[{text:e("Alboko azalera.","Área lateral.","المساحة الجانبية."),math:i("$2\\cdot 3{,}14\\cdot 0{,}5\\cdot 2=6{,}28$")},{text:e("Bi oinarriak.","Las dos bases.","القاعدتان."),math:i("$2\\cdot 3{,}14\\cdot 0{,}5^{2}=1{,}57$")},{text:e("Guztira 7,85 m².","En total, 7,85 m².","المجموع 7.85 م²."),math:i("$6{,}28+1{,}57=7{,}85$")}],example:i("$A_L=2\\pi r h\\qquad A_T=2\\pi r h+2\\pi r^{2}$"),takeaway:e("Zilindroa: laukizuzen bat ($2\\pi r$ zabal) eta bi zirkulu.","Cilindro: un rectángulo ($2\\pi r$ de ancho) y dos círculos.","الأسطوانة: مستطيل (عرضه $2\\pi r$) ودائرتان."),figure:t=>n.jsx(I,{language:t})},{id:"cone",stage:"round",title:e("Konoa eta kono-enborra","El cono y el tronco de cono","المخروط وجذع المخروط"),goal:e("Konoaren elementuak lotzea Pitagorasekin eta konoaren eta kono-enborraren azalera kalkulatzea.","Relacionar los elementos del cono con Pitágoras y calcular el área del cono y del tronco de cono.","ربط عناصر المخروط بفيثاغورس وحساب مساحة المخروط وجذع المخروط."),explanation:e("Konoa triangelu angeluzuzen bat kateto baten inguruan biratuz sortzen da. Kateto hori altuera da ($h$), beste katetoa oinarriaren erradioa ($r$) eta hipotenusa sortzailea ($g$): $g=\\sqrt{h^{2}+r^{2}}$. Konoaren garapena sektore zirkular bat eta zirkulu bat dira; sektorearen erradioa sortzailea da. Alboko azalera $A_L=\\pi r g$ da, eta azalera osoa $A_T=\\pi r g+\\pi r^{2}$. Kono-enborra trapezio angeluzuzen bat biratuz sortzen da; bi oinarri ditu, $R$ eta $r$ erradiokoak, eta alboko azalera $A_L=\\pi (R+r)\\,g$ da. Haren sortzailea ere Pitagorasekin: $g=\\sqrt{h^{2}+(R-r)^{2}}$.","El cono se genera al girar un triángulo rectángulo alrededor de un cateto. Ese cateto es la altura ($h$), el otro cateto el radio de la base ($r$) y la hipotenusa, la generatriz ($g$): $g=\\sqrt{h^{2}+r^{2}}$. El desarrollo del cono es un sector circular y un círculo; el radio del sector es la generatriz. El área lateral es $A_L=\\pi r g$ y el área total, $A_T=\\pi r g+\\pi r^{2}$. El tronco de cono se genera al girar un trapecio rectángulo; tiene dos bases de radios $R$ y $r$, y su área lateral es $A_L=\\pi (R+r)\\,g$. Su generatriz, también con Pitágoras: $g=\\sqrt{h^{2}+(R-r)^{2}}$.","ينشأ المخروط بدوران مثلث قائم حول أحد ضلعيه القائمين. هذا الضلع هو الارتفاع ($h$)، والضلع الآخر نصف قطر القاعدة ($r$)، والوتر هو الراسم ($g$): $g=\\sqrt{h^{2}+r^{2}}$. نشر المخروط قطاع دائري ودائرة؛ ونصف قطر القطاع هو الراسم. المساحة الجانبية $A_L=\\pi r g$ والمساحة الكلية $A_T=\\pi r g+\\pi r^{2}$. وينشأ جذع المخروط بدوران شبه منحرف قائم؛ له قاعدتان نصفا قطريهما $R$ و$r$، ومساحته الجانبية $A_L=\\pi (R+r)\\,g$. وراسمه أيضًا بفيثاغورس: $g=\\sqrt{h^{2}+(R-r)^{2}}$."),problem:e("Kono batek 6 cm-ko erradioa eta 8 cm-ko altuera ditu. Kalkulatu azalera osoa.","Un cono tiene 6 cm de radio y 8 cm de altura. Calcula su área total.","مخروط نصف قطره 6 سم وارتفاعه 8 سم. احسب مساحته الكلية."),stepsKind:"steps",steps:[{text:e("Sortzailea.","Generatriz.","الراسم."),math:i("$g=\\sqrt{8^{2}+6^{2}}=10$")},{text:e("Alboko azalera.","Área lateral.","المساحة الجانبية."),math:i("$3{,}14\\cdot 6\\cdot 10=188{,}4$")},{text:e("Gehitu oinarria.","Suma la base.","أضف القاعدة."),math:i("$188{,}4+3{,}14\\cdot 36=301{,}44$")}],example:i("$A_L=\\pi r g\\qquad A_L=\\pi (R+r)\\,g$"),takeaway:e("Konoa: $g^{2}=h^{2}+r^{2}$ eta $A_L=\\pi r g$. Ez nahastu altuera eta sortzailea.","Cono: $g^{2}=h^{2}+r^{2}$ y $A_L=\\pi r g$. No confundas altura y generatriz.","المخروط: $g^{2}=h^{2}+r^{2}$ و$A_L=\\pi r g$. لا تخلط بين الارتفاع والراسم."),figure:t=>n.jsx(O,{language:t})},{id:"sphere",stage:"round",title:e("Esfera","La esfera","الكرة"),goal:e("Esferaren, kasketaren eta zona esferikoaren azalera kalkulatzea eta esferaren sekzioak ulertzea.","Calcular el área de la esfera, del casquete y de la zona esférica y entender las secciones de la esfera.","حساب مساحة الكرة والقبعة والمنطقة الكروية وفهم مقاطع الكرة."),explanation:e("Esfera zirkulu-erdi bat bere diametroaren inguruan biratuz sortzen da. Ezin da garatu (ezin da laua bihurtu hautsi gabe), baina Arkimedesek aurkitu zuen haren azalera zilindro zirkunskribatuaren alboko azalera bezainbestekoa dela: $A=4\\pi r^{2}$, lau zirkulu handi. Esfera bi plano paralelok mozten badute, haien arteko zatia zona esferikoa da; plano bakar batek mozten badu, kasketa esferikoa. Bien azalera zilindroaren banda bera da: $A=2\\pi r h$, $h$ zonaren altuera izanik. Plano batek esfera mozten duenean, sekzioa zirkulua da; zentrotik $d$ distantziara, haren erradioa $\\sqrt{r^{2}-d^{2}}$ da.","La esfera se genera al girar un semicírculo alrededor de su diámetro. No se puede desarrollar (no se puede aplanar sin romperla), pero Arquímedes descubrió que su área es igual al área lateral del cilindro circunscrito: $A=4\\pi r^{2}$, cuatro círculos máximos. Si dos planos paralelos cortan la esfera, la parte entre ellos es una zona esférica; si la corta un solo plano, un casquete esférico. El área de ambos es la de la banda del cilindro: $A=2\\pi r h$, siendo $h$ la altura de la zona. Cuando un plano corta la esfera, la sección es un círculo; a una distancia $d$ del centro, su radio es $\\sqrt{r^{2}-d^{2}}$.","تنشأ الكرة بدوران نصف دائرة حول قطرها. لا يمكن نشرها (لا يمكن جعلها مستوية دون تمزيقها)، لكن أرخميدس اكتشف أن مساحتها تساوي المساحة الجانبية للأسطوانة المحيطة بها: $A=4\\pi r^{2}$، أي أربع دوائر عظمى. إذا قطع الكرةَ مستويان متوازيان فالجزء بينهما منطقة كروية؛ وإذا قطعها مستوٍ واحد فقبعة كروية. ومساحة كلتيهما مساحة شريط الأسطوانة: $A=2\\pi r h$ حيث $h$ ارتفاع المنطقة. وعندما يقطع مستوٍ الكرة يكون المقطع دائرة؛ وعلى بعد $d$ من المركز يكون نصف قطرها $\\sqrt{r^{2}-d^{2}}$."),problem:e("Kalkulatu 10 cm-ko erradioko esfera baten azalera eta 4 cm-ko altuerako zona batena.","Calcula el área de una esfera de 10 cm de radio y la de una zona de 4 cm de altura.","احسب مساحة كرة نصف قطرها 10 سم ومساحة منطقة ارتفاعها 4 سم."),stepsKind:"steps",steps:[{text:e("Esfera osoa.","Esfera completa.","الكرة كاملة."),math:i("$4\\cdot 3{,}14\\cdot 10^{2}=1256$")},{text:e("Zona: zilindroaren banda.","Zona: la banda del cilindro.","المنطقة: شريط الأسطوانة."),math:i("$2\\cdot 3{,}14\\cdot 10\\cdot 4=251{,}2$")}],example:i("$A=4\\pi r^{2}\\qquad A=2\\pi r h$"),takeaway:e("Esfera: $4\\pi r^{2}$. Zona eta kasketa: $2\\pi r h$.","Esfera: $4\\pi r^{2}$. Zona y casquete: $2\\pi r h$.","الكرة: $4\\pi r^{2}$. المنطقة والقبعة: $2\\pi r h$."),figure:t=>n.jsx(G,{language:t})},{id:"volume-units",stage:"units",title:e("Bolumen-unitateak","Unidades de volumen","وحدات الحجم"),goal:e("Bolumen-unitateak elkarren artean aldatzea, mailaz maila 1000 bider biderkatuz edo zatituz.","Pasar de unas unidades de volumen a otras, multiplicando o dividiendo por 1000 en cada escalón.","التحويل بين وحدات الحجم بالضرب أو القسمة على 1000 في كل درجة."),explanation:e("Gorputz baten bolumena hartzen duen espazioa da. Unitatea metro kubikoa da (m³): metro bateko ertza duen kuboa. Haren azpimultiploak dm³, cm³ eta mm³ dira, eta multiploak dam³, hm³ eta km³. Dezimetro kubiko batean $10\\cdot 10\\cdot 10=1000$ zentimetro kubiko sartzen dira: luzeran 10 aldiz, zabaleran 10 eta altueran 10. Horregatik, maila bakoitza hurrengoa baino 1000 aldiz handiagoa da: unitate txikiago batera jaisteko, biderkatu 1000z maila bakoitzeko; handiago batera igotzeko, zatitu. Adibidez, $2{,}5\\ \\text{m}^{3}=2500\\ \\text{dm}^{3}$ eta $4500\\ \\text{cm}^{3}=4{,}5\\ \\text{dm}^{3}$.","El volumen de un cuerpo es el espacio que ocupa. La unidad es el metro cúbico (m³): un cubo de un metro de arista. Sus submúltiplos son dm³, cm³ y mm³, y sus múltiplos dam³, hm³ y km³. En un decímetro cúbico caben $10\\cdot 10\\cdot 10=1000$ centímetros cúbicos: 10 a lo largo, 10 a lo ancho y 10 a lo alto. Por eso cada escalón es 1000 veces el siguiente: para bajar a una unidad menor, multiplica por 1000 en cada escalón; para subir, divide. Por ejemplo, $2{,}5\\ \\text{m}^{3}=2500\\ \\text{dm}^{3}$ y $4500\\ \\text{cm}^{3}=4{,}5\\ \\text{dm}^{3}$.","حجم الجسم هو الحيز الذي يشغله. ووحدته المتر المكعب (م³): مكعب طول حرفه متر. وأجزاؤه dm³ وcm³ وmm³، ومضاعفاته dam³ وhm³ وkm³. في الديسيمتر المكعب $10\\cdot 10\\cdot 10=1000$ سنتيمتر مكعب: 10 طولًا و10 عرضًا و10 ارتفاعًا. لذلك كل درجة تساوي 1000 مرة الدرجة التالية: للنزول إلى وحدة أصغر اضرب في 1000 لكل درجة؛ وللصعود اقسم. مثلًا $2{,}5\\ \\text{m}^{3}=2500\\ \\text{dm}^{3}$ و$4500\\ \\text{cm}^{3}=4{,}5\\ \\text{dm}^{3}$."),problem:e("Adierazi 0,3 m³ cm³-tan.","Expresa 0,3 m³ en cm³.","عبّر عن 0.3 م³ بالسنتيمتر المكعب."),stepsKind:"steps",steps:[{text:e("m³-tik cm³-ra bi maila jaisten dira.","De m³ a cm³ se bajan dos escalones.","من m³ إلى cm³ ننزل درجتين."),math:i("$1000\\cdot 1000=1\\,000\\,000$")},{text:e("Biderkatu.","Multiplica.","اضرب."),math:i("$0{,}3\\cdot 1\\,000\\,000=300\\,000$")}],example:i("$1\\ \\text{m}^{3}=1000\\ \\text{dm}^{3}=1\\,000\\,000\\ \\text{cm}^{3}$"),takeaway:e("Bolumenean maila bakoitza 1000 da: hiru zifra koma bakoitzeko jauzian.","En volumen, cada escalón es 1000: tres cifras por salto.","في الحجم كل درجة 1000: ثلاثة أرقام لكل قفزة."),figure:t=>n.jsx(R,{language:t})},{id:"capacity",stage:"units",title:e("Bolumena eta edukiera","Volumen y capacidad","الحجم والسعة"),goal:e("Bolumen-unitateak eta edukiera-unitateak lotzea: 1 dm³ = 1 L.","Relacionar las unidades de volumen con las de capacidad: 1 dm³ = 1 L.","ربط وحدات الحجم بوحدات السعة: 1 dm³ = 1 L."),explanation:e("Ontzi baten edukiera barruan har dezakeen likido kopurua da, eta litrotan (L) neurtzen da. Litro bat dezimetro bateko ertza duen kubo bat betetzeko behar den likidoa da: $1\\ \\text{dm}^{3}=1\\ \\text{L}$. Hortik: $1\\ \\text{cm}^{3}=1\\ \\text{mL}$ eta $1\\ \\text{m}^{3}=1000\\ \\text{L}$. Edukiera-unitateak 10ean-10ean doaz (kL, hL, daL, L, dL, cL, mL), bolumenekoak 1000ean-1000ean. Gainera, ur litro batek kilo bat pisatzen du gutxi gorabehera. Euria ere horrela neurtzen da: metro karratu bakoitzeko litro batek milimetro bateko ur-geruza egiten du.","La capacidad de un recipiente es la cantidad de líquido que cabe dentro y se mide en litros (L). Un litro es el líquido necesario para llenar un cubo de un decímetro de arista: $1\\ \\text{dm}^{3}=1\\ \\text{L}$. De ahí: $1\\ \\text{cm}^{3}=1\\ \\text{mL}$ y $1\\ \\text{m}^{3}=1000\\ \\text{L}$. Las unidades de capacidad van de 10 en 10 (kL, hL, daL, L, dL, cL, mL) y las de volumen de 1000 en 1000. Además, un litro de agua pesa aproximadamente un kilo. Así se mide también la lluvia: un litro por metro cuadrado forma una capa de agua de un milímetro.","سعة الإناء كمية السائل التي يمكن أن يحتويها، وتقاس باللتر (L). اللتر هو السائل اللازم لملء مكعب طول حرفه ديسيمتر: $1\\ \\text{dm}^{3}=1\\ \\text{L}$. ومن ذلك: $1\\ \\text{cm}^{3}=1\\ \\text{mL}$ و$1\\ \\text{m}^{3}=1000\\ \\text{L}$. تتدرج وحدات السعة عشرة عشرة (kL، hL، daL، L، dL، cL، mL)، ووحدات الحجم ألفًا ألفًا. ثم إن لتر الماء يزن كيلوغرامًا تقريبًا. وهكذا يقاس المطر أيضًا: لتر على كل متر مربع يكوّن طبقة ماء سُمكها مليمتر."),problem:e("Igerileku batek 12 m × 6 m × 1,5 m neurtzen ditu. Zenbat litro ur sartzen dira?","Una piscina mide 12 m × 6 m × 1,5 m. ¿Cuántos litros de agua caben?","مسبح أبعاده 12 م × 6 م × 1.5 م. كم لترًا من الماء يسع؟"),stepsKind:"steps",steps:[{text:e("Bolumena m³-tan.","Volumen en m³.","الحجم بالمتر المكعب."),math:i("$12\\cdot 6\\cdot 1{,}5=108$")},{text:e("1 m³ = 1000 L.","1 m³ = 1000 L.","1 m³ = 1000 L."),math:i("$108\\cdot 1000=108\\,000$")}],example:i("$1\\ \\text{dm}^{3}=1\\ \\text{L}\\qquad 1\\ \\text{cm}^{3}=1\\ \\text{mL}$"),takeaway:e("1 dm³ = 1 L = 1 kg ur. 1 m³ = 1000 L.","1 dm³ = 1 L = 1 kg de agua. 1 m³ = 1000 L.","1 dm³ = 1 L = 1 kg من الماء. 1 m³ = 1000 L."),figure:t=>n.jsx(F,{language:t})},{id:"cavalieri",stage:"units",title:e("Ortoedroa eta Cavalieriren printzipioa","El ortoedro y el principio de Cavalieri","متوازي المستطيلات ومبدأ كافاليري"),goal:e("Ortoedroaren bolumena unitate-kuboak zenbatuz ulertzea eta Cavalieriren printzipioa aplikatzea.","Entender el volumen del ortoedro contando cubos unidad y aplicar el principio de Cavalieri.","فهم حجم متوازي المستطيلات بعدّ مكعبات الوحدة وتطبيق مبدأ كافاليري."),explanation:e("Ortoedro bat unitate-kuboekin betetzen badugu, beheko geruzan luzera bider zabalera kubo sartzen dira, eta altuera adina geruza daude. Beraz, $V=a\\cdot b\\cdot c$: oinarriaren azalera bider altuera. Kuboan, $V=l^{3}$. Bonaventura Cavalierik printzipio hau eman zuen: bi gorputzek altuera bera badute eta oinarriarekiko paraleloak diren plano guztiek azalera bereko sekzioak sortzen badituzte, bolumen bera dute. Txanpon-pila zuzen batek eta okertu batek bolumen bera dute. Horregatik, prisma zeihar baten bolumena prisma zuzen batena bezala kalkulatzen da, eta formula berak balio du edozein prismatarako.","Si llenamos un ortoedro con cubos unidad, en la capa de abajo caben largo por ancho cubos, y hay tantas capas como la altura. Por eso $V=a\\cdot b\\cdot c$: área de la base por altura. En el cubo, $V=l^{3}$. Bonaventura Cavalieri dio este principio: si dos cuerpos tienen la misma altura y todos los planos paralelos a la base cortan secciones de la misma área, tienen el mismo volumen. Una pila de monedas recta y otra inclinada tienen el mismo volumen. Por eso el volumen de un prisma oblicuo se calcula como el de uno recto, y la misma fórmula vale para cualquier prisma.","إذا ملأنا متوازي مستطيلات بمكعبات الوحدة ففي الطبقة السفلى عدد من المكعبات يساوي الطول في العرض، وعدد الطبقات يساوي الارتفاع. لذلك $V=a\\cdot b\\cdot c$: مساحة القاعدة في الارتفاع. وفي المكعب $V=l^{3}$. وضع بونافنتورا كافاليري هذا المبدأ: إذا كان لجسمين الارتفاع نفسه وكانت جميع المستويات الموازية للقاعدة تقطع منهما مقاطع متساوية المساحة فلهما الحجم نفسه. لكومة نقود مستقيمة وأخرى مائلة الحجم نفسه. لذلك يُحسب حجم المنشور المائل كالمنشور القائم، والصيغة نفسها تصلح لكل منشور."),problem:e("Kaxa batek 25 cm × 20 cm × 16 cm neurtzen ditu. Zein da haren bolumena litrotan?","Una caja mide 25 cm × 20 cm × 16 cm. ¿Cuál es su volumen en litros?","صندوق أبعاده 25 سم × 20 سم × 16 سم. ما حجمه باللتر؟"),stepsKind:"steps",steps:[{text:e("Biderkatu hiru neurriak.","Multiplica las tres medidas.","اضرب الأبعاد الثلاثة."),math:i("$25\\cdot 20\\cdot 16=8000$")},{text:e("1000 cm³ = 1 L.","1000 cm³ = 1 L.","1000 cm³ = 1 L."),math:i("$8000\\mathbin{:}1000=8$")}],example:i("$V=a\\cdot b\\cdot c\\qquad V=l^{3}$"),takeaway:e("Ortoedroa: luzera · zabalera · altuera. Sekzio berdinak eta altuera bera → bolumen bera.","Ortoedro: largo · ancho · alto. Mismas secciones y misma altura → mismo volumen.","متوازي المستطيلات: الطول · العرض · الارتفاع. مقاطع متساوية وارتفاع واحد ← حجم واحد."),figure:t=>n.jsx(D,{language:t})},{id:"prism-volume",stage:"volume",title:e("Prismaren eta zilindroaren bolumena","Volumen del prisma y del cilindro","حجم المنشور والأسطوانة"),goal:e("Prismen eta zilindroen bolumena oinarriaren azalera bider altuera gisa kalkulatzea.","Calcular el volumen de prismas y cilindros como área de la base por altura.","حساب حجم المناشير والأسطوانات بوصفه مساحة القاعدة في الارتفاع."),explanation:e("Cavalieriren printzipioaren arabera, oinarri bereko azalera eta altuera bera dituzten prisma guztiek ortoedroaren bolumen bera dute. Beraz, edozein prismatan eta zilindrotan: $V=A_O\\cdot h$. Lehenik oinarriaren azalera kalkulatzen da (triangelua, trapezioa, poligono erregularra…), eta gero altuerarekin biderkatzen da. Zilindroan oinarria zirkulua da: $V=\\pi r^{2}h$. Gorputz konposatuetan, zatitu gorputz ezagunetan eta batu (edo kendu, zulo bat badago) bolumenak. Emaitza litrotan eskatzen badute, gogoratu $1\\ \\text{dm}^{3}=1\\ \\text{L}$.","Según el principio de Cavalieri, todos los prismas con base de la misma área e igual altura tienen el volumen del ortoedro. Por eso, en cualquier prisma y cilindro: $V=A_B\\cdot h$. Primero se calcula el área de la base (triángulo, trapecio, polígono regular…) y luego se multiplica por la altura. En el cilindro la base es un círculo: $V=\\pi r^{2}h$. En los cuerpos compuestos, divide en cuerpos conocidos y suma (o resta, si hay un hueco) los volúmenes. Si piden el resultado en litros, recuerda que $1\\ \\text{dm}^{3}=1\\ \\text{L}$.","وفق مبدأ كافاليري، لجميع المناشير التي لقواعدها المساحة نفسها والارتفاع نفسه حجمُ متوازي المستطيلات. لذلك في أي منشور وأسطوانة: $V=A_B\\cdot h$. تُحسب أولًا مساحة القاعدة (مثلث، شبه منحرف، مضلع منتظم…) ثم تُضرب في الارتفاع. وفي الأسطوانة القاعدة دائرة: $V=\\pi r^{2}h$. وفي الأجسام المركبة قسّم إلى أجسام معروفة واجمع الحجوم (أو اطرح إذا كان فيها تجويف). وإذا طُلبت النتيجة باللتر فتذكّر أن $1\\ \\text{dm}^{3}=1\\ \\text{L}$."),problem:e("Lata zilindriko batek 4 cm-ko erradioa eta 10 cm-ko altuera ditu. Zenbat cm³ sartzen dira?","Una lata cilíndrica tiene 4 cm de radio y 10 cm de altura. ¿Cuántos cm³ caben?","علبة أسطوانية نصف قطرها 4 سم وارتفاعها 10 سم. كم سم³ تسع؟"),stepsKind:"steps",steps:[{text:e("Oinarria: zirkulua.","Base: un círculo.","القاعدة: دائرة."),math:i("$3{,}14\\cdot 4^{2}=50{,}24$")},{text:e("Bider altuera.","Por la altura.","في الارتفاع."),math:i("$50{,}24\\cdot 10=502{,}4$")},{text:e("Ia erdi litro: 0,5024 L.","Casi medio litro: 0,5024 L.","نحو نصف لتر: 0.5024 L.")}],example:e("$V=A_O\\cdot h\\qquad V=\\pi r^{2}h$","$V=A_B\\cdot h\\qquad V=\\pi r^{2}h$","$V=A_B\\cdot h\\qquad V=\\pi r^{2}h$"),takeaway:e("Prisma eta zilindroa: oinarriaren azalera bider altuera.","Prisma y cilindro: área de la base por altura.","المنشور والأسطوانة: مساحة القاعدة في الارتفاع."),figure:t=>n.jsx(H,{language:t})},{id:"pyramid-volume",stage:"volume",title:e("Piramidearen eta konoaren bolumena","Volumen de la pirámide y del cono","حجم الهرم والمخروط"),goal:e("Piramideen eta konoen bolumena prisma eta zilindro baten heren gisa kalkulatzea.","Calcular el volumen de pirámides y conos como un tercio de un prisma y un cilindro.","حساب حجم الأهرامات والمخاريط بوصفه ثلث منشور وأسطوانة."),explanation:e("Piramide bat urez bete eta oinarri eta altuera bereko prisma batera hustuz gero, hiru aldiz egin behar da prisma betetzeko. Beraz, piramidearen bolumena prismaren herena da: $V=\\frac{A_O\\cdot h}{3}$. Gauza bera gertatzen da konoarekin eta zilindroarekin: $V=\\frac{\\pi r^{2}h}{3}$. Kontuz: formulan altuera erabiltzen da, ez apotema edo sortzailea; behar bada, Pitagorasekin kalkulatzen da. Enborren bolumena bi gorputzen kendura da: piramide handia ken moztutako piramide txikia.","Si llenamos de agua una pirámide y la vaciamos en un prisma de igual base y altura, hay que hacerlo tres veces para llenar el prisma. Por eso el volumen de la pirámide es un tercio del del prisma: $V=\\frac{A_B\\cdot h}{3}$. Lo mismo pasa con el cono y el cilindro: $V=\\frac{\\pi r^{2}h}{3}$. Cuidado: en la fórmula va la altura, no la apotema ni la generatriz; si hace falta, se calcula con Pitágoras. El volumen de los troncos es la resta de dos cuerpos: la pirámide grande menos la pequeña que se ha cortado.","إذا ملأنا هرمًا بالماء وأفرغناه في منشور له القاعدة والارتفاع نفسهما فعلينا تكرار ذلك ثلاث مرات لملء المنشور. لذلك حجم الهرم ثلث حجم المنشور: $V=\\frac{A_B\\cdot h}{3}$. والأمر نفسه في المخروط والأسطوانة: $V=\\frac{\\pi r^{2}h}{3}$. انتبه: في الصيغة يدخل الارتفاع لا العامد ولا الراسم؛ وعند الحاجة يُحسب بفيثاغورس. وحجم الجذوع فرق جسمين: الهرم الكبير ناقص الهرم الصغير المقطوع."),problem:e("Kono baten sortzailea 10 cm da eta erradioa 6 cm. Kalkulatu bolumena.","La generatriz de un cono mide 10 cm y el radio 6 cm. Calcula su volumen.","راسم مخروط 10 سم ونصف قطره 6 سم. احسب حجمه."),stepsKind:"steps",steps:[{text:e("Altuera Pitagorasekin.","La altura con Pitágoras.","الارتفاع بفيثاغورس."),math:i("$h=\\sqrt{10^{2}-6^{2}}=8$")},{text:e("Zilindroaren herena.","Un tercio del cilindro.","ثلث الأسطوانة."),math:i("$\\frac{3{,}14\\cdot 36\\cdot 8}{3}=301{,}44$")}],example:e("$V=\\frac{A_O\\cdot h}{3}\\qquad V=\\frac{\\pi r^{2}h}{3}$","$V=\\frac{A_B\\cdot h}{3}\\qquad V=\\frac{\\pi r^{2}h}{3}$","$V=\\frac{A_B\\cdot h}{3}\\qquad V=\\frac{\\pi r^{2}h}{3}$"),takeaway:e("Piramidea eta konoa: prismaren eta zilindroaren herena. Altuera, ez apotema.","Pirámide y cono: un tercio del prisma y del cilindro. Altura, no apotema.","الهرم والمخروط: ثلث المنشور والأسطوانة. الارتفاع لا العامد."),figure:t=>n.jsx(M,{language:t})},{id:"sphere-volume",stage:"volume",title:e("Esferaren bolumena eta problemak","Volumen de la esfera y problemas","حجم الكرة والمسائل"),goal:e("Esferaren bolumena kalkulatzea eta gorputz konposatuen eta eguneroko bolumen-problemak ebaztea.","Calcular el volumen de la esfera y resolver problemas de cuerpos compuestos y volúmenes cotidianos.","حساب حجم الكرة وحل مسائل الأجسام المركبة والحجوم اليومية."),explanation:e("Arkimedesek erakutsi zuen esferaren bolumena zilindro zirkunskribatuaren bi heren dela: zilindroak $\\pi r^{2}\\cdot 2r=2\\pi r^{3}$ du, eta esferak $V=\\frac{4}{3}\\pi r^{3}$. Erdiesferak erdia du. Problemetan: identifikatu gorputzak, idatzi datuak unitate berean, kalkulatu bolumen bakoitza eta batu edo kendu. Adibidez, kaxa batean bolak sartzen badira, geratzen den hutsunea kaxaren bolumena ken bolen bolumena da. Amaieran, eman emaitza eskatutako unitatean (L, m³…) eta egiaztatu zentzuzkoa dela.","Arquímedes demostró que el volumen de la esfera es dos tercios del de su cilindro circunscrito: el cilindro tiene $\\pi r^{2}\\cdot 2r=2\\pi r^{3}$ y la esfera, $V=\\frac{4}{3}\\pi r^{3}$. La semiesfera tiene la mitad. En los problemas: identifica los cuerpos, escribe los datos en la misma unidad, calcula cada volumen y suma o resta. Por ejemplo, si metemos bolas en una caja, el hueco que queda es el volumen de la caja menos el de las bolas. Al final, da el resultado en la unidad pedida (L, m³…) y comprueba que tiene sentido.","برهن أرخميدس أن حجم الكرة ثلثا حجم الأسطوانة المحيطة بها: للأسطوانة $\\pi r^{2}\\cdot 2r=2\\pi r^{3}$ وللكرة $V=\\frac{4}{3}\\pi r^{3}$. ولنصف الكرة النصف. في المسائل: حدّد الأجسام، واكتب المعطيات بالوحدة نفسها، واحسب كل حجم ثم اجمع أو اطرح. مثلًا إذا وضعنا كرات في صندوق فالفراغ الباقي حجم الصندوق ناقص حجم الكرات. وفي النهاية أعطِ النتيجة بالوحدة المطلوبة (L، m³…) وتحقّق من معقوليتها."),problem:e("Kalkulatu 3 cm-ko erradioko bola baten bolumena.","Calcula el volumen de una bola de 3 cm de radio.","احسب حجم كرة نصف قطرها 3 سم."),stepsKind:"steps",steps:[{text:e("Erradioaren kuboa.","El cubo del radio.","مكعب نصف القطر."),math:i("$3^{3}=27$")},{text:e("Formula.","La fórmula.","الصيغة."),math:i("$\\frac{4\\cdot 3{,}14\\cdot 27}{3}=113{,}04$")}],example:i("$V=\\frac{4}{3}\\pi r^{3}$"),takeaway:e("Esfera: $\\frac{4}{3}\\pi r^{3}$, zilindroaren bi heren. Konposatuak: zatitu, kalkulatu, batu edo kendu.","Esfera: $\\frac{4}{3}\\pi r^{3}$, dos tercios del cilindro. Compuestos: divide, calcula, suma o resta.","الكرة: $\\frac{4}{3}\\pi r^{3}$، ثلثا الأسطوانة. المركبة: قسّم واحسب واجمع أو اطرح."),figure:t=>n.jsx(N,{language:t})}],ya={polyhedron:ea,platonic:aa,box:X,pyramid:J,round:Y,tank:Q,volume:W};function fa(t){return n.jsx(P,{...t,tools:m,stages:x,components:ya,title:{eu:"Eraiki, garatu eta bete",es:"Construye, desarrolla y llena",ar:"أنشئ وانشر واملأ"}})}const La={storagePrefix:"matella-gorputzak-dbh2",coursePath:"/matematika/dbh2",courseTitle:{eu:"2. DBH",es:"2.º ESO",ar:"الصف الثاني"},title:{eu:"Gorputz geometrikoak",es:"Cuerpos geométricos",ar:"الأجسام الهندسية"},documentTitle:{eu:"Gorputz geometrikoak · 2. DBH",es:"Cuerpos geométricos · 2.º ESO",ar:"الأجسام الهندسية · الصف الثاني"},tagline:{eu:"Poliedroak eta Euler, prismak, piramideak, zilindroak, konoak eta esferak: haien garapenak, azalerak eta bolumenak, litroetaraino.",es:"Poliedros y Euler, prismas, pirámides, cilindros, conos y esferas: sus desarrollos, sus áreas y sus volúmenes, hasta los litros.",ar:"متعددات الأوجه وأويلر، والمناشير والأهرامات والأسطوانات والمخاريط والكرات: نشرها ومساحاتها وحجومها حتى اللترات."},heroArt:n.jsx(ia,{}),pathSubtitle:{eu:"Bost etapa, poliedroetatik bolumenetara",es:"Cinco etapas, de los poliedros a los volúmenes",ar:"خمس مراحل، من متعددات الأوجه إلى الحجوم"},stages:x,topics:xa,diagnostic:da,guidedPractice:la,exerciseBank:ua,challenges:sa,lab:{description:{eu:`${m.length} tresna gorputzak ukitzeko: prismak eta piramideak, bost poliedro erregularrak, kaxa eta haren garapena, piramidearen apotema, zilindroa, konoa eta esfera, depositua litrotan eta bolumenak konparatzeko, erronkekin.`,es:`${m.length} herramientas para tocar los cuerpos: prismas y pirámides, los cinco poliedros regulares, la caja y su desarrollo, la apotema de la pirámide, cilindro, cono y esfera, el depósito en litros y comparar volúmenes, con retos.`,ar:`${m.length} أدوات للمس الأجسام: المناشير والأهرامات، ومتعددات الأوجه المنتظمة الخمسة، والصندوق ونشره، وعامد الهرم، والأسطوانة والمخروط والكرة، والخزان باللترات، ومقارنة الحجوم، مع تحديات.`},progressIds:oa,toolForTopic:ta,render:t=>n.jsx(fa,{...t})},games:{description:{eu:"Bi joko abiadura eta zehaztasuna entrenatzeko: lasterketa eta memoria.",es:"Dos juegos para entrenar rapidez y precisión: carrera y memoria.",ar:"لعبتان لتدريب السرعة والدقة: السباق والذاكرة."},progressIds:ca,recordsKey:h,render:t=>n.jsx(ha,{...t})},answers:{note:{eu:"Idatzi zenbaki bat, komarekin edo puntuarekin (188,4 edo 188.4), unitaterik gabe. Erabili π ≈ 3,14.",es:"Escribe un número, con coma o con punto (188,4 o 188.4), sin la unidad. Usa π ≈ 3,14.",ar:"اكتب عددًا بالنقطة أو بالفاصلة (188.4) دون الوحدة. استعمل π ≈ 3.14."},defaultForm:"any",inputMode:"decimal",normalizeInput:ra,placeholder:()=>({eu:"Adib.: 188,4",es:"Ej.: 188,4",ar:"مثال: 188.4"}),wrongForm:()=>({eu:"Balioa zuzena da, baina idatzi zenbaki gisa.",es:"El valor es correcto, pero escríbelo como número.",ar:"القيمة صحيحة، لكن اكتبها عددًا."}),unreadable:{eu:"Ez dut erantzun hori ulertzen. Idatzi zenbaki bat, adibidez 120 edo 188,4.",es:"No entiendo esa respuesta. Escribe un número, por ejemplo 120 o 188,4.",ar:"لم أفهم هذه الإجابة. اكتب عددًا، مثل 120 أو 188.4."}},errorByStage:{polyhedra:{eu:"Prisma: n + 2 aurpegi, 3n ertz, 2n erpin. Piramidea: n + 1, 2n, n + 1. Euler: aurpegiak + erpinak = ertzak + 2.",es:"Prisma: n + 2 caras, 3n aristas, 2n vértices. Pirámide: n + 1, 2n, n + 1. Euler: caras + vértices = aristas + 2.",ar:"المنشور: n + 2 وجهًا و3n حرفًا و2n رأسًا. الهرم: n + 1 و2n وn + 1. أويلر: الأوجه + الرؤوس = الأحرف + 2."},areas:{eu:"Marraztu garapena: alboko aurpegiak gehi oinarriak. Piramidean apotema erabili, ez altuera.",es:"Dibuja el desarrollo: caras laterales más bases. En la pirámide usa la apotema, no la altura.",ar:"ارسم النشر: الأوجه الجانبية مع القاعدتين. في الهرم استعمل العامد لا الارتفاع."},round:{eu:"Zilindroa: 2πrh. Konoa: πrg. Esfera: 4πr². Diametroa ematen badute, erdia hartu.",es:"Cilindro: 2πrh. Cono: πrg. Esfera: 4πr². Si dan el diámetro, toma la mitad.",ar:"الأسطوانة: 2πrh. المخروط: πrg. الكرة: 4πr². إذا أُعطي القطر فخذ نصفه."},units:{eu:"Bolumenean maila bakoitza 1000 da. 1 dm³ = 1 L eta 1 cm³ = 1 mL.",es:"En volumen cada escalón es 1000. 1 dm³ = 1 L y 1 cm³ = 1 mL.",ar:"في الحجم كل درجة 1000. 1 dm³ = 1 L و1 cm³ = 1 mL."},volume:{eu:"Prisma eta zilindroa: oinarria · altuera. Piramidea eta konoa: herena. Esfera: 4πr³ : 3.",es:"Prisma y cilindro: base · altura. Pirámide y cono: un tercio. Esfera: 4πr³ : 3.",ar:"المنشور والأسطوانة: القاعدة · الارتفاع. الهرم والمخروط: الثلث. الكرة: 4πr³ : 3."}}};function Va(){return n.jsx(A,{unit:La})}export{Va as GorputzakIntroPage};
